#region "Extract Pressures"
    private HashSet<StrategyPressureEvidence> ExtractPressures( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        return psi.Strategy switch
        {
            PairStrategy.EstablishTrickRoom         => ExtractPressures_EstablishTrickRoom( psi, poe ),
            PairStrategy.EstablishTailwind          => ExtractPressures_EstablishTailwind( psi, poe ),
            PairStrategy.WeatherPivot               => ExtractPressures_WeatherPivot( psi, poe ),
            PairStrategy.SecureImmediateKO          => ExtractPressures_SecureImmediateKO( psi, poe ),
            PairStrategy.ApplyBoardPressure         => ExtractPressures_ApplyBoardPressure( psi, poe ),
            PairStrategy.PreserveTempo              => ExtractPressures_PreserveTempo( psi, poe ),
            PairStrategy.DenyOpponentSetup          => ExtractPressures_DenyOpponentSetup( psi, poe ),
            PairStrategy.EstablishDefensivePosition => ExtractPressures_EstablishDefensivePosition( psi, poe ),
            PairStrategy.AfterYouAttack             => ExtracPressures_AfterYouAttack( psi, poe ),
            _ => new(),
        };
    }

    private StrategyPressureEvidence BuildStrategyPressureEvidence( PairStrategyIntent psi, PairObservationEvidence poe, StrategyPressure pressure )
    {

        return new()
        {
            Pressure = pressure,
            SourceStrategy = psi,
            SourceAction = poe.IsPrimary ? poe.SourceIntent.PrimaryIntent.IntentResult.ActionType : poe.SourceIntent.SecondaryIntent.IntentResult.ActionType,
            SourceActionResult = poe.IsPrimary ? poe.SourceIntent.PrimaryIntent.IntentResult : poe.SourceIntent.SecondaryIntent.IntentResult,
        };
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_EstablishTrickRoom( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--EstablishSpeedControl -> implicit
            //--EnableSafeSetup -> Cover, Fake Out, Guard, Redirection
            //--ProtectSetter -> Cover
            //--SetupMomentum -> Setup

            //--Implicit
            //--StrategyPressure.EstablishSpeedControl
        };

        //--Implicit SPE
        foreach( var e in poe )
        {
            if( e.Type == PairObservation.TrickRoom )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EstablishSpeedControl ) );
                break;
            }
        }


        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.Cover:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectSetter ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;

                case PairObservation.FakeOutSupport:
                case PairObservation.GuardSupport:
                case PairObservation.RedirectionSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;

                case PairObservation.Setup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.SetupMomentum ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.AttackAndSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.SetupMomentum ) );
                break;

                case PairPattern.CoveredSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectSetter ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_EstablishTailwind( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--EstablishSpeedControl -> implicit
            //--EnableSafeSetup -> Cover, Fake Out, Guard, Redirection
            //--ApplyImmediatePressure -> Attack, AttackAndSetup
            //--SetupMomentum -> implicit

            //--Implicit
            // StrategyPressure.EstablishSpeedControl,
            // StrategyPressure.SetupMomentum,
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Tailwind )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EstablishSpeedControl ) );
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.SetupMomentum ) );
                break;
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.Cover:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectSetter ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;

                case PairObservation.Attack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;

                case PairObservation.FakeOutSupport:
                case PairObservation.GuardSupport:
                case PairObservation.RedirectionSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.AttackAndSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;

                case PairPattern.CoveredSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectSetter ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafeSetup ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_WeatherPivot( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures -> Observation/Pattern
            //--MaintainWeatherControl -> implicit
            //--PreservePivotUnit -> Preservation
            //--EnableSafePivot -> Cover
            //--MaintainMomentum -> PivotPressure or PivotMove or AttackAndSwitch pattern

            //--Implict
            // StrategyPressure.WeatherChange
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.WeatherChange )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.WeatherChange ) );
                break;
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.Preservation:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.PreserveUnit ) );
                break;

                case PairObservation.Cover:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafePivot ) );
                break;

                case PairObservation.PivotMove:
                case PairObservation.PivotPressure:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainMomentum ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.AttackAndSwitch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainMomentum ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_SecureImmediateKO( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--ImmediateRemoval -> implicit
            //--ConcentrateDamage -> FocusFire
            //--GuaranteeRemoval -> DoubleAttack
            //--PunishWeakTarget -> RevengeKO

            //--Implicit
            // StrategyPressure.ImmediateRemoval
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Attack )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ImmediateRemoval ) );
                break;
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.RevengeKO:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.PunishWeakTarget ) );
                break;

                case PairObservation.DoubleAttack:

                    if( TryGetObservationProfile( e, PairObservation.FocusFire, out var ff ) )
                        pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.GuaranteeRemoval ) );

                break;

                case PairObservation.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ConcentrateDamage ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.DoubleAttack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.GuaranteeRemoval ) );
                break;

                case PairPattern.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ConcentrateDamage ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_ApplyBoardPressure( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--MaintainMomentum -> AttackAndSetup, AttackAndSwitch + PivotMove/PivotPressure Observation, CoveredAttack
            //--ApplyOffensivePressure -> implicit
            //--ConcentrateDamage -> FocusFire
            //--ThreatenMultipleLines -> AttackAndSetup, AttackAndSwitch, FakeOutSupport

            //--Implicit
            // StrategyPressure.ApplyOffensivePressure,
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Attack || e.Type == PairObservation.SpreadAttack )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.SpreadAttack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ThreatenMultipleLines ) );
                break;

                case PairObservation.DoubleAttack:
                
                    if( TryGetObservationProfile( e, PairObservation.FocusFire, out var ff ) )
                        pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ThreatenMultipleLines ) );

                break;

                case PairObservation.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ConcentrateDamage ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.AttackAndSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainMomentum ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ThreatenMultipleLines ) );
                break;

                case PairPattern.AttackAndSwitch:

                    if( TryGetObservationProfile( e, PairObservation.PivotMove, out var pm ) || TryGetObservationProfile( e, PairObservation.PivotPressure, out var pp ) )
                        pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainMomentum ) );

                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ThreatenMultipleLines ) );

                break;

                case PairPattern.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ConcentrateDamage ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_PreserveTempo( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--MaintainMomentum -> implicit
            //--PreserveUnit -> Preservation, CoveredSwitch
            //--EnableSafePivot -> CoveredSwitch
            //--RetainInitiative -> AttackAndSwitch, ProtectAndSwitch, AttackAndSetup

            //--Implicit
            // StrategyPressure.MaintainMomentum,
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Switch )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainMomentum ) );
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.Preservation:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.PreserveUnit ) );
                break;

                case PairObservation.Cover:
                case PairObservation.FakeOutSupport:
                case PairObservation.RedirectionSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.RetainInitiative ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.CoveredSwitch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.PreserveUnit ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EnableSafePivot ) );
                break;

                case PairPattern.AttackAndSetup:
                case PairPattern.AttackAndSwitch:
                case PairPattern.ProtectAndSwitch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.RetainInitiative ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_DenyOpponentSetup( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--InterruptSetup -> implicit
            //--DenyResources -> FakeOutSupport, Interruption, StatusDisruption
            //--ApplyOffensivePressure -> FocusFire, FakeOutSupport
            //--ActFirst -> SpeedControl
            //--ProtectDisruptor, FakeOutSupport, Redirection, GuardSupport

            //--Implicit Pressures
            // StrategyPressure.InterruptSetup,
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Interruption )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.InterruptSetup ) );
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                break;
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.FakeOutSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectDisruptor ) );
                break;

                case PairObservation.StatusDisruption:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                break;

                case PairObservation.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;

                case PairObservation.SpeedControl:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ActFirst ) );
                break;

                case PairObservation.RedirectionSupport:
                case PairObservation.GuardSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectDisruptor ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.CoveredAttack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;

                case PairPattern.FocusFire:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                break;

                case PairPattern.DisruptionPressure:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                break;

                case PairPattern.CoveredSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.DenyResources ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtractPressures_EstablishDefensivePosition( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Pressures
            //--ReduceIncomingPressure -> DefensivePlay, ProtectAndSwitch // Protect, ScreensSupport, GuardSupport
            //--IncreaseBoardStability -> implicit
            //--ProtectImportantUnit -> CoveredSetup, CoveredSwitch, ProtectAndSwitch // Cover, Protect
            //--CreateDefensiveResources -> DefensivePlay, CoveredSetup + ScreensSupport // ScreensSupport
            //--MaintainLongevity -> PivotPlay, CoveredSwitch, ProtectAndSwitch // Protect

            //--Implicit
            // StrategyPressure.IncreaseBoardStability,
        };

        foreach( var e in poe )
        {
            if( e.Type == PairObservation.Protect || e.Type == PairObservation.ScreensSupport || e.Type == PairObservation.GuardSupport || e.Type ==  PairObservation.Switch )
            {
                pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.IncreaseBoardStability ) );
            }
        }

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.Protect:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainLongevity ) );
                break;

                case PairObservation.ScreensSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.CreateDefensiveResources ) );
                break;

                case PairObservation.GuardSupport:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                break;

                case PairObservation.Cover:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );
                break;

                case PairObservation.Switch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainLongevity ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );
                break;
            }

            switch( e.SourcePattern )
            {
                case PairPattern.DefensivePlay:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.CreateDefensiveResources ) );
                break;

                case PairPattern.ProtectAndSwitch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ReduceIncomingPressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainLongevity ) );
                break;

                case PairPattern.CoveredSetup:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );

                    if( TryGetObservationProfile( e, PairObservation.ScreensSupport, out var scs ) )
                        pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.CreateDefensiveResources ) );
                break;

                case PairPattern.CoveredSwitch:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ProtectImportantUnit ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainLongevity ) );
                break;

                case PairPattern.PivotPlay:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.MaintainLongevity ) );
                break;
            }
        }

        return pressures;
    }

    private HashSet<StrategyPressureEvidence> ExtracPressures_AfterYouAttack( PairStrategyIntent psi, List<PairObservationEvidence> poe )
    {
        HashSet<StrategyPressureEvidence> pressures = new()
        {
            //--Patterns: AfterYouAndAttack
            //--Observations: AfterYou, StatusMove, SpeedControl, Attack, SpreadAttack
            // AfterYouAndAttack Pattern -> ApplyOffensivePressure
            // Attack -> PunishWeakTarget, ImmediateRemoval
            // SpreadAttack GuaranteeRemoval, PunishWeakTarget, ThreatenMultipleLines
            //--Implicit -> AfterYou, ActFirst
        };

        foreach( var e in poe )
        {
            switch( e.Type )
            {
                case PairObservation.AfterYou:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.AfterYou ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ActFirst ) );
                break;

                case PairObservation.SpeedControl:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.EstablishSpeedControl ) );
                break;

                case PairObservation.Attack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ApplyOffensivePressure ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ImmediateRemoval ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.PunishWeakTarget ) );
                break;

                case PairObservation.SpreadAttack:
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.GuaranteeRemoval ) );
                    pressures.Add( BuildStrategyPressureEvidence( psi, e, StrategyPressure.ThreatenMultipleLines ) );
                break;

            }
        }

        return pressures;
    }

