#region "Find Capability Helpers"

    private void FindActionControlCapability( List<IBattleAIUnit> ourActive, List<IBattleAIUnit> ourBench, Dictionary<Pokemon, HashSet<CapabilityObservation>> observations )
    {
        //--Options
        // Fake Out
        // Taunt
        // Encore
        // Disable
        // Torment
        // Imprison
        // Phazing

        void AddObservation( Pokemon pokemon, CapabilityObservation observation )
        {
            if( observations.ContainsKey( pokemon ) )
                observations[pokemon].Add( observation );
            else
                observations.Add( pokemon, new(){ observation } );
        }

        void SearchForCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( _ai.CanUseFakeOut( unit ) )
                AddObservation( unit.Pokemon, CapabilityObservation.FakeOut );

            if( traits.Contains( RoleTrait.Taunt ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Taunt );

            if( traits.Contains( RoleTrait.Encore ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Encore );

            if( unit.Pokemon.CheckHasActiveMove( "Disable" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Disable );

            if( unit.Pokemon.CheckHasActiveMove( "Torment" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Torment );

            if( unit.Pokemon.CheckHasActiveMove( "Imprison" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Imprison );

            if( traits.Contains( RoleTrait.Phazes ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Phazing );

            if( unit.Ability == AbilityID.Prankster )
                AddObservation( unit.Pokemon, CapabilityObservation.Prankster );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.ParalysisPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Paralysis );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.SleepPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Sleep );
        }

        //--Only Active units matter here
        foreach( var unit in ourActive )
            SearchForCapability( unit );

        //--Not true, Fake Out is a powerful switch-in capability, it just doesn't activate the same turn as the switch. --09/24/26
        foreach( var unit in ourBench )
        {
            if( _ai.CanUseFakeOut( unit ) )
                AddObservation( unit.Pokemon, CapabilityObservation.FakeOut );
        }
    }

    private void FindProtectionCapability( List<IBattleAIUnit> ourActive, List<IBattleAIUnit> ourBench, Dictionary<Pokemon, HashSet<CapabilityObservation>> observations )
    {
        //--Options
        // Redirection
        // Wide Guard
        // Quick Guard
        // Crafty Shield
        // Mat Block
        // Armor Tail, Dazzling, Queenly Majesty
        // Psychic Surge
        // Screens

        void AddObservation( Pokemon pokemon, CapabilityObservation observation )
        {
            if( observations.ContainsKey( pokemon ) )
                observations[pokemon].Add( observation );
            else
                observations.Add( pokemon, new(){ observation } );
        }

        void SearchForCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( traits.Contains( RoleTrait.RedirectionMove ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Redirection );

            if( unit.Pokemon.CheckHasActiveMove( "Wide Guard" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.WideGuard );

            if( unit.Pokemon.CheckHasActiveMove( "Quick Guard" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.QuickGuard );

            if( unit.Pokemon.CheckHasActiveMove( "Crafty Shield" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.CraftyShield );

            if( _ai.CanUseMatBlock( unit ) )
                AddObservation( unit.Pokemon, CapabilityObservation.MatBlock );

            if( traits.Contains( RoleTrait.ScreenSetter) )
            {
                if( unit.Pokemon.CheckHasActiveMove( "Reflect" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.Reflect );

                if( unit.Pokemon.CheckHasActiveMove( "Light Screen" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.LightScreen );

                if( unit.Pokemon.CheckHasActiveMove( "Aurora Veil" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.AuroraVeil );
            }

            if( traits.Contains( RoleTrait.PriorityBlockAbility ) && unit.Ability == AbilityID.PsychicSurge )
                AddObservation( unit.Pokemon, CapabilityObservation.AbilityPriorityBlock );   

            if( unit.Ability == AbilityID.PsychicSurge )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.AbilityPriorityBlock );
                AddObservation( unit.Pokemon, CapabilityObservation.TerrainSetAbility );
            }

            if( unit.Pokemon.CheckHasActiveMove( "Substitute" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Substitute );

            if( unit.Pokemon.CheckHasActiveMove( "Shed Tail" ) )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.Substitute );
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );
            }
        }

        void SearchForIncomingCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( traits.Contains( RoleTrait.PriorityBlockAbility ) && unit.Ability != AbilityID.PsychicSurge )
                AddObservation( unit.Pokemon, CapabilityObservation.AbilityPriorityBlock );   

            if( unit.Ability == AbilityID.PsychicSurge )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.AbilityPriorityBlock );
                AddObservation( unit.Pokemon, CapabilityObservation.TerrainSetAbility );
            }
        }

        //--Active Units
        foreach( var unit in ourActive )
            SearchForCapability( unit );

        //--Bench
        foreach( var unit in ourBench )
            SearchForIncomingCapability( unit );
    }

    private void FindPressureCapability( List<IBattleAIUnit> ourActive, List<IBattleAIUnit> ourBench, Dictionary<Pokemon, HashSet<CapabilityObservation>> observations )
    {
        //--Options
        // Intimidate
        // Demoralize
        // Will-O-Wisp
        // Hoarfrost Spirit
        // Paralysis moves
        // Sleep moves
        // Stat Debuff
        // Attack & Debuff hybrid (icy wind, snarl)
        // Knock Off
        // Throat Chop

        void AddObservation( Pokemon pokemon, CapabilityObservation observation )
        {
            if( observations.ContainsKey( pokemon ) )
                observations[pokemon].Add( observation );
            else
                observations.Add( pokemon, new(){ observation } );
        }

        void SearchForCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( unit.Ability == AbilityID.Intimidate )
                AddObservation( unit.Pokemon, CapabilityObservation.Intimidate );
            
            if( unit.Ability == AbilityID.Demoralize )
                AddObservation( unit.Pokemon, CapabilityObservation.Demoralize );

            if( unit.Pokemon.CheckHasActiveMove( "Will-O-Wisp" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Wisp );

            if( unit.Pokemon.CheckHasActiveMove( "Hoarfrost Spirit" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Hoarfrost );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.ParalysisPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Paralysis );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.SleepPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Sleep );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.PoisonPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Poison );

            if( unit.RoleProfile.Traits.Contains( RoleTrait.ToxicPressure ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Toxic );

            if( traits.Contains( RoleTrait.StatDebuffer ) )
                AddObservation( unit.Pokemon, CapabilityObservation.StatDebuff );

            if( _ai.UnitSim.PokemonHasMove_AttackAndDebuffHybrid( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.HybridDebuff );

            if( unit.Pokemon.CheckHasActiveMove( "Knock Off" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.KnockOff );

            if( unit.Pokemon.CheckHasActiveMove( "Throat Chop" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.ThroatChop );
        }

        void SearchForIncomingCapability( IBattleAIUnit unit )
        {
            if( unit.Ability == AbilityID.Intimidate )
                AddObservation( unit.Pokemon, CapabilityObservation.Intimidate );
            
            if( unit.Ability == AbilityID.Demoralize )
                AddObservation( unit.Pokemon, CapabilityObservation.Demoralize );
        }

        //--Active Units
        foreach( var unit in ourActive )
            SearchForCapability( unit );

        //--Bench
        foreach( var unit in ourBench )
            SearchForIncomingCapability( unit );
    }

    private void FindBoardControlCapability( List<IBattleAIUnit> ourActive, List<IBattleAIUnit> ourBench, Dictionary<Pokemon, HashSet<CapabilityObservation>> observations )
    {
        //--Options
        // Weather Set Ability

        // Weather Set Move

        // Terrain Set Ability
        // Terain Set Move

        // Tailwind
        // Trick Room

        // Hazards
        // Hazard Removal
        // Stat Reset
        // Defog
        // Tidy Up

        void AddObservation( Pokemon pokemon, CapabilityObservation observation )
        {
            if( observations.ContainsKey( pokemon ) )
                observations[pokemon].Add( observation );
            else
                observations.Add( pokemon, new(){ observation } );
        }

        void SearchForCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( _ai.UnitSim.PokemonHasWeatherSetter_Ability( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.WeatherSetAbility );

            if( _ai.UnitSim.PokemonHasWeatherSetter_Move( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.WeatherSetMove );

            if( _ai.UnitSim.PokemonHasTerrainSetter_Ability( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.TerrainSetAbility );

            if( _ai.UnitSim.PokemonHasTerrainSetter_Move( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.TerrainSetMove );

            if( traits.Contains( RoleTrait.TailwindSetter ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Tailwind );

            if( traits.Contains( RoleTrait.TrickRoomSetter ) )
                AddObservation( unit.Pokemon, CapabilityObservation.TrickRoom );

            if( traits.Contains( RoleTrait.ScreenSetter) )
            {
                if( unit.Pokemon.CheckHasActiveMove( "Reflect" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.Reflect );

                if( unit.Pokemon.CheckHasActiveMove( "Light Screen" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.LightScreen );

                if( unit.Pokemon.CheckHasActiveMove( "Aurora Veil" ) )
                    AddObservation( unit.Pokemon, CapabilityObservation.AuroraVeil );
            }

            if( traits.Contains( RoleTrait.HazardSetter ) )
                AddObservation( unit.Pokemon, CapabilityObservation.HazardSetting );

            if( unit.Pokemon.CheckHasActiveMove( "Rapid Spin" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.RapidSpin );

            if( unit.Pokemon.CheckHasActiveMove( "Mortal Spin" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.MortalSpin );

            if( unit.Pokemon.CheckHasActiveMove( "Defog" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.Defog );

            if( unit.Pokemon.CheckHasActiveMove( "Haze" ) || unit.Pokemon.CheckHasActiveMove( "Clear Smog" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.StatReset );

            if( unit.Pokemon.CheckHasActiveMove( "Tidy Up" ) )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.TidyUp );
                AddObservation( unit.Pokemon, CapabilityObservation.SubstituteBypass );
            }

            if( unit.Ability == AbilityID.Prankster )
                AddObservation( unit.Pokemon, CapabilityObservation.Prankster );
        }

        void SearchForIncomingCapability( IBattleAIUnit unit )
        {
            if( _ai.UnitSim.PokemonHasWeatherSetter_Ability( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.WeatherSetAbility );

            if( _ai.UnitSim.PokemonHasTerrainSetter_Ability( unit.Pokemon ) )
                AddObservation( unit.Pokemon, CapabilityObservation.TerrainSetAbility );
        }

        //--Active Units
        foreach( var unit in ourActive )
            SearchForCapability( unit );

        //--Bench
        foreach( var unit in ourBench )
            SearchForIncomingCapability( unit );
    }

    private void FindPositioningCapability( List<IBattleAIUnit> ourActive, List<IBattleAIUnit> ourBench, Dictionary<Pokemon, HashSet<CapabilityObservation>> observations )
    {
        //--Options
        // Pivot Move

        // Phazing

        // Ally Switch
        // Baton Pass

        void AddObservation( Pokemon pokemon, CapabilityObservation observation )
        {
            if( observations.ContainsKey( pokemon ) )
                observations[pokemon].Add( observation );
            else
                observations.Add( pokemon, new(){ observation } );
        }

        void SearchForCapability( IBattleAIUnit unit )
        {
            var rp = unit.RoleProfile;
            var traits = rp.Traits;

            if( unit.Pokemon.CheckHasActiveMove( "U-Turn" ) || unit.Pokemon.CheckHasActiveMove( "Volt Switch" ) || unit.Pokemon.CheckHasActiveMove( "Flip Turn" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );

            if( unit.Pokemon.CheckHasActiveMove( "Parting Shot" ) )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );
                AddObservation( unit.Pokemon, CapabilityObservation.StatDebuff );
            }

            if( unit.Pokemon.CheckHasActiveMove( "Shed Tail" ) )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );
                AddObservation( unit.Pokemon, CapabilityObservation.Substitute );
            }

            if( unit.Pokemon.CheckHasActiveMove( "Ally Switch" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.AllySwitch );

            if( unit.Pokemon.CheckHasActiveMove( "Baton Pass" ) )
            {
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );
                AddObservation( unit.Pokemon, CapabilityObservation.BatonPass );
            }

            if( unit.Pokemon.CheckHasActiveMove( "Teleport" ) )
                AddObservation( unit.Pokemon, CapabilityObservation.PivotMove );
        }

        //--Active Units
        foreach( var unit in ourActive )
            SearchForCapability( unit );
    }

