            WeCan = weCan,
            AllyCan = allyCan,
        };
    }

    private CoordinationAction GetAttackCandidate( CapabilityObservation capability, IBattleAIUnit us, IBattleAIUnit them, CoordinationActionType type )
    {
        // CustomLogSession candidateLog = new();
        Move moveCandidate = null;

        // candidateLog.Add( $"Getting Attack Candidate...({capability}, {us.Name} vs {them.Name})" );
        switch( capability )
        {
            case CapabilityObservation.FakeOut:
                if( TryExtractMoveFromPokemon( "Fake Out", us, out var fakeOut ) )
                    moveCandidate = fakeOut;
            break;

            case CapabilityObservation.KnockOff:
                if( TryExtractMoveFromPokemon( "Knock Off", us, out var knockOff ) )
                    moveCandidate = knockOff;
            break;

            case CapabilityObservation.ThroatChop:
                if( TryExtractMoveFromPokemon( "Throat Chop", us, out var throatChop ) )
                    moveCandidate = throatChop;
            break;

            case CapabilityObservation.BrickBreak:
                if( TryExtractMoveFromPokemon( "Brick Break", us, out var brickBreak ) )
                    moveCandidate = brickBreak;

            break;

            case CapabilityObservation.PsychicFangs:
                if( TryExtractMoveFromPokemon( "Psychic Fangs", us, out var psychicFangs ) )
                    moveCandidate = psychicFangs;

            break;

            case CapabilityObservation.RapidSpin:
                if( TryExtractMoveFromPokemon( "Rapid Spin", us, out var rapidSpin ) )
                    moveCandidate = rapidSpin;

            break;

            case CapabilityObservation.MortalSpin:
                if( TryExtractMoveFromPokemon( "Mortal Spin", us, out var mortalSpin ) )
                    moveCandidate = mortalSpin;

            break;

            case CapabilityObservation.HybridDebuff:

                //--Gotta figure out how to reconcile which hybrid debuff move to select
                //--if a pokemon has more than one. realistically it will likely never be
                //--that a pokemon has both snarl and icy wind for example, but it's not impossible
                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsAttackAndDebuffHybrid( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }

            break;

            case CapabilityObservation.StrongestAttack:

                var usComp_Them = _ai.Projection.MakeUnitComparison( us, them );
                moveCandidate = usComp_Them.Attacker.CurrentPTKOs.Keys.First();

            break;

            case CapabilityObservation.CoverageMove:

                var theirBench = GetPokemonBench( them.Pokemon );
                int bestPTKO = int.MinValue;
                Move bestCoverageMove = null;
                foreach( var move in us.ActiveMoves )
                {
                    if( move.MoveSO.MoveCategory == MoveCategory.Status )
                        continue;

                    MoveThreatResult ourMTR = new(){ Move = move }; //--or setting target count here
                    int ptko = 0;

                    foreach( var unit in theirBench )
                    {
                        ourMTR.Targets = new(){ unit };
                        float effectiveness = _ai.UnitSim.Get_MoveEffectiveness( unit, move );
                        float modifier = _ai.UnitSim.Get_MoveModifier( us, unit, move );
                        ourMTR.Modifier = effectiveness * modifier;

                        var ourEDR = _ai.Projection.Get_EstimatedDamageResult( us, unit, ourMTR );
                        var ourPTKO = _ai.Projection.Get_PotentialToKOResult( ourEDR, ourMTR, unit ).PTKO;

                        ptko += (int)ourPTKO;
                    }

                    if( ptko > bestPTKO )
                    {
                        bestPTKO = ptko;
                        bestCoverageMove = move;
                    }
                }

                moveCandidate = bestCoverageMove;

            break;
        }

        // candidateLog.Add( $"Move Candidate: {moveCandidate?.MoveSO.Name}" );
        // Debug.Log( candidateLog.ToString() );
        // candidateLog.Clear();
        
        return new()
        {
            Type = type,
            ActionType = ActionType.Attack,

            Actor = us.Pokemon,
            Target = them.Pokemon,

            MoveCandidate = moveCandidate,
            SwitchCandidate = null,

            Capability = capability,
        };
    }

    private CoordinationAction GetSwitchCandidate( CapabilityObservation capability, IBattleAIUnit us, IBattleAIUnit switchCandidate, IBattleAIUnit them, CoordinationActionType type )
    {
