                                }

                                if( currentTerrain == TerrainID.Grassy )
                                {
                                    if( theyUseAMove && theirMove != null && theirMove.MoveType == PokemonType.Grass && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                        var theirEDR = theirMTR.EDR;

                                        if( them.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) || them.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirMTR.TargetCount > 1 )
                                            boardFit += theirMTR.TargetCount;
                                    }

                                    if( theirAllyHasIntent && theirAllyUsesMove && theirAllyMove != null && theirAllyMove.MoveType == PokemonType.Grass  && theirAllyMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                        var theirAllyEDR = theirAllyMTR.EDR;

                                        if( theirAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirAllyMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirAllyPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirAllyMTR.TargetCount > 1 )
                                            boardFit += theirAllyMTR.TargetCount;
                                    }
                                }

                                if( currentTerrain == TerrainID.Misty )
                                {
                                    if( theyUseAMove && theirMove != null && theirMove.MoveType == PokemonType.Fairy && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                        var theirEDR = theirMTR.EDR;

                                        if( them.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainAbuser ) || them.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirMTR.TargetCount > 1 )
                                            boardFit += theirMTR.TargetCount;
                                    }

                                    if( theirAllyHasIntent && theirAllyUsesMove && theirAllyMove != null && theirAllyMove.MoveType == PokemonType.Fairy  && theirAllyMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                        var theirAllyEDR = theirAllyMTR.EDR;

                                        if( theirAlly.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainAbuser ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirAllyMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirAllyPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirAllyMTR.TargetCount > 1 )
                                            boardFit += theirAllyMTR.TargetCount;
                                    }
                                }

                                if( currentTerrain == TerrainID.Psychic )
                                {
                                    if( theyUseAMove && theirMove != null && theirMove.MoveType == PokemonType.Psychic && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                        var theirEDR = theirMTR.EDR;

                                        if( them.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) || them.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirMTR.TargetCount > 1 )
                                            boardFit += theirMTR.TargetCount;
                                    }

                                    if( theirAllyHasIntent && theirAllyUsesMove && theirAllyMove != null && theirAllyMove.MoveType == PokemonType.Psychic  && theirAllyMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                        var theirAllyEDR = theirAllyMTR.EDR;

                                        if( theirAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainHelps ) )
                                            boardFit += 1;

                                        Stat attackStat = theirAllyMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeTerrainModifier = 1.3f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, removeModifier: removeTerrainModifier );

                                        if( adjustedPTKO < theirAllyPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirAllyMTR.TargetCount > 1 )
                                            boardFit += theirAllyMTR.TargetCount;
                                    }
                                }
                            }
                        }
                    }
                    
                    //--This is more of an opportunity capability than a response capability.
                    //--you can't prevent a target from switching if they have already submitted the switch command this turn
                    //--so checking to see if they are thinking of switching, or using a strategy that requires switching
                    //--doesn't matter because you cannot apply shadow tag to a unit who has already submitted a switch command to the queue.
                    //--it only applies to units trying to switching while tag is already on the field
                    if( mainCapability == CapabilityObservation.TrapAbility )
                    {
                        boardFit += 1;

                        if( weHaveAlly && ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.PerishSong ) )
                            boardFit += 2;

                        if( them.BeginningHPR <= 0.33f )
                            boardFit += 1;

                        if( theyHaveAlly && theirAlly.BeginningHPR <= 0.33f )
                            boardFit += 1;

                        if( ourAllyPTKO_Them >= PotentialToKO.TwoHKO )
                            boardFit += 1;

                        if( ourAllyPTKO_TheirAlly >= PotentialToKO.TwoHKO )
                            boardFit += 1;

                        offensiveAlignment++;
                    }
                    
                    if( mainCapability == CapabilityObservation.Hospitality && ourAlly != null )
                    {
                        defensiveAlignment++;

                        if( ourAlly.BeginningHPR <= 0.33f )
                            boardFit += 3;
                        else if( ourAlly.BeginningHPR <= 0.66f )
                            boardFit += 2;
                        else if( ourAlly.BeginningHPR <= 1f )
                            boardFit += 1;

                        if( targetsOurAlly && theirMove != null && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                        {
                            var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                            var theirEDR = theirMTR.EDR;
                            Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                            Stat defenseStat = attackStat == Stat.Attack ? Stat.Attack : Stat.SpAttack;
                            
                            var newHPR = ourAlly.BeginningHPR + 0.25f;
                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackStat, defenseStat, newHPR: newHPR );

                            if( adjustedPTKO < theirPTKO_OurAlly )
                                boardFit += 1;

                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurAlly - adjustedPTKO >= 2 )
                                boardFit += 1;
                        }
                    }

                    //--Unit Fit
                    //--general role checks
                    //--current unit roles
                    bool ourHPLow = us.BeginningHPR <= 0.5f;

                    if( ourHPLow && MovesBefore( them, us, turnOrder ) )
                        unitFit += 1;

                    if( ourPTKO <= PotentialToKO.TwoHKO && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                    {
                        unitFit += 1;
                        offensiveAlignment++;
                    }

                    if( MovesBefore( them, us, turnOrder ) && ourPTKO <= PotentialToKO.Risky && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                        unitFit += 1;

                    if( ourHPLow && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive )
                    {
                        unitFit += 1;
                        defensiveAlignment++;
                    }

                    if( ourHPLow && MovesBefore( them, us, turnOrder ) && us.Ability != AbilityID.Prankster && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        unitFit += 1;

                    //--switch candidate roles
                    bool switchHPLow = ourSwitch.BeginningHPR <= 0.5f;

                    if( ourSwitch?.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                    {
                        unitFit += 1;

                        if( mainCapability == CapabilityObservation.Intimidate || mainCapability == CapabilityObservation.Demoralize || mainCapability == CapabilityObservation.TrapAbility || mainCapability == CapabilityObservation.AbilityPriorityBlock )
                            unitFit += 1;
                    }

                    if( ourSwitch?.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                    {
                        if( mainCapability == CapabilityObservation.WeatherSetAbility )
                        {
                            if( switchesWeather != currentWeather && _ai.UnitSim.PokemonHasMove_AbusesWeather( ourSwitch.Pokemon, switchesWeather ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }
                        }

                        if( mainCapability == CapabilityObservation.TerrainSetAbility )
                        {
                            if( switchesTerrain == TerrainID.Blighted && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainAbuser ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }

                            if( switchesTerrain == TerrainID.Electric && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainAbuser ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }

                            if( switchesTerrain == TerrainID.Grassy && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }

                            if( switchesTerrain == TerrainID.Misty && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainAbuser ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }

                            if( switchesTerrain == TerrainID.Psychic && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                            {
                                unitFit += 1;
                                offensiveAlignment++;
                            }
                        }
                    }

                    //--ptko exchanges
                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                    {
                        unitFit += 1;
                        defensiveAlignment++;

                        if( ourPTKO <= PotentialToKO.Risky || MovesBefore( them, us, turnOrder ) )
                            unitFit += 1;
                    }

                    if( theirPTKO_OurSwitch >= PotentialToKO.Dangerous )
                    {
                        unitFit -= 1;

                        if( switchHPLow )
                            unitFit -= 1;

                        if( mainCapability == CapabilityObservation.WeatherSetAbility )
                        {
                            if( theirSP.DependsOnCurrentWeather || theirAllySP.DependsOnCurrentWeather )
                            {
                                unitFit += 1;
                            }
                        }
                    }

                    //--speed comparisons
                    if( them.Speed > us.Speed && ourSwitch.Speed > them.Speed )
                        unitFit += 1;

                    if( mainCapability == CapabilityObservation.WeatherSetAbility )
                    {
                        if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( them.Pokemon, currentWeather ) )
                        {
                            offensiveAlignment++;

                            if( them.Pokemon.Speed / 2 < ourSwitch.Speed || them.Pokemon.Speed / 2 < ourAlly?.Speed )
                                unitFit += 1;
                        }

                        if( theirAlly != null && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( theirAlly.Pokemon, currentWeather ) )
                        {
                            offensiveAlignment++;

                            if( theirAlly.Pokemon.Speed / 2 < ourSwitch.Speed || theirAlly.Pokemon.Speed / 2 < ourAlly?.Speed )
                                unitFit += 1;
                        } 
                    }

                    if( activeCapabilitySets.Count > 0 && mainCapability == CapabilityObservation.RawSwitch )
                        unitFit += 1;

                    //--current unit has other relevant action response capabilities
                    int otherRelevantCapabilities = 0;
                    foreach( var kvp in activeCapabilitySets )
                    {
                        var p = kvp.Value;

                        foreach( var spe in p )
                        {
                            if( spe.ResponseCapabilities.TryGetValue( us.Pokemon, out var caps ) )
                            {
                                foreach( var c in caps )
                                {
                                    if( GetCapabilityActionType( c ) != ActionType.DefensiveSwitch )
                                        otherRelevantCapabilities++;
                                }
                            }
                        }
                    }

                    unitFit -= otherRelevantCapabilities;

                    //--Plan Fit
                    bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                    bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                    bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                    bool ourallyIsWincon = ourAlly != null && ourAlly.Pokemon == gp.OurPrimaryWinCon;
                    bool ourAllyIsBlocker = ourAlly != null && gp.OurBlockers.Contains( ourAlly.Pokemon );
                    bool ourAllyIsEnabler = ourAlly != null && gp.OurEnablers.Contains( ourAlly.Pokemon );

                    bool ourSwitchIsWincon = ourSwitch != null && ourSwitch.Pokemon == gp.OurPrimaryWinCon;
                    bool ourSwitchIsBlocker = ourSwitch != null && gp.OurBlockers.Contains( ourSwitch.Pokemon );
                    bool ourSwitchIsEnabler = ourSwitch != null && gp.OurEnablers.Contains( ourSwitch.Pokemon );

                    bool theyAreWincon = them.Pokemon == gp.TheirPrimaryWinCon;
                    bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                    bool theyAreEnabler = gp.TheirEnablers.Contains( them.Pokemon );

                    bool theirAllyIsWincon = theirAlly != null && theirAlly.Pokemon == gp.TheirPrimaryWinCon;
                    bool theirAllyIsBlocker = theirAlly != null && gp.TheirBlockers.Contains( theirAlly.Pokemon );
                    bool theirAllyIsEnabler = theirAlly != null && gp.TheirEnablers.Contains( theirAlly.Pokemon );

                    if( weAreWincon && ( theyAreBlocker || theirAllyIsBlocker ) )
                    {
                        planFit += 1;
                        defensiveAlignment++;
                    }

                    if( ( ourSwitchIsWincon && ourAllyIsEnabler ) || ( ourSwitchIsEnabler && ourallyIsWincon ) )
                    {
                        planFit += 1;
                        offensiveAlignment++;
                    }

                    if( ( theyAreWincon || theirAllyIsWincon ) && ourSwitchIsBlocker )
                    {
                        planFit += 1;
                        defensiveAlignment++;
                    }

                    if( ourSwitchIsWincon && ( theyAreBlocker || theirAllyIsBlocker ) )
                    {
                        planFit -= 1;

                        if( theyAreBlocker && theirAllyIsBlocker )
                            planFit -= 1;
                    }

                    if( CheckIfPokemonHasSpecificCapability( us.Pokemon, CapabilityObservation.WeatherSetAbility, activeCapabilitySets ) )
                    {
                        var ourTeamComp = _ai.Blackboard.OurTeamComposition;
                        if( currentWeather == WeatherConditionID.Sun && ourTeamComp.Strategies.Contains( TeamStrategy.Sun ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                        {
                            planFit += 1;
                            offensiveAlignment++;
                        }

                        if( currentWeather == WeatherConditionID.Rain && ourTeamComp.Strategies.Contains( TeamStrategy.Rain ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                        {
                            planFit += 1;
                            offensiveAlignment++;
                        }

                        if( currentWeather == WeatherConditionID.Sand && ourTeamComp.Strategies.Contains( TeamStrategy.Sand ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                        {
                            planFit += 1;
                            offensiveAlignment++;
                        }

                        if( currentWeather == WeatherConditionID.Snow && ourTeamComp.Strategies.Contains( TeamStrategy.Snow ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                        {
                            planFit += 1;
                            offensiveAlignment++;
                        }
                    }

                    //--Cost/Risk
                    //--Switch Tax
                    costRisk += 1;

                    if( theirPTKO_OurSwitch >= PotentialToKO.Dangerous )
                    {
                        costRisk += 1;
                    }

                    if( theirAllyPTKO_OurSwitch >= PotentialToKO.Dangerous )
                    {
                        costRisk += 1;
                    }

                    if( targetsOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                        costRisk += 1;

                    if( theirAllyTargetsOurAlly && theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                        costRisk += 1;

                    if( targetsOurAlly && theirAllyTargetsOurAlly )
                    {
                        if( theirPTKO_OurAlly >= PotentialToKO.Risky && theirAllyPTKO_OurAlly >= PotentialToKO.Risky )
                            costRisk += 1;
                    }

                    if( theirAllyTargetsUs )
                    {
                        costRisk += 1;

                        if( targetsUs )
                            costRisk += 1;
                    }

                    if( usIP.AttackerMovesFirst && ourPTKO >= PotentialToKO.Dangerous )
                        costRisk += 1;

                    int otherCapabilityActions = 0;
                    foreach( var kvp in pressureSets )
                    {
                        var spe = kvp.Value;

                        if( spe.ResponseCapabilities.TryGetValue( us.Pokemon, out var caps ) )
                        {
                            foreach( var c in caps )
                            {
                                if( GetCapabilityActionType( c ) != ActionType.DefensiveSwitch )
                                    otherCapabilityActions++;
                            }
                        }
                    }

                    if( otherCapabilityActions > 3 )
                        costRisk += 3;
                    else if( otherCapabilityActions > 1 )
                        costRisk += 2;
                    else if( otherCapabilityActions > 0 )
                        costRisk += 1;

                    if( theirAction != ActionType.Attack && theirAction != ActionType.Protect )
                    {
                        if( us.RoleProfile.Traits.Contains( RoleTrait.PriorityBlockAbility ) && them.Ability == AbilityID.Prankster )
                            costRisk += 1;

                        if( usIP.WeCan.FakeOut )
                            costRisk += 1;
                    }

                    if( theirAllyHasIntent && theirAllyTargetsUs && theirAllyAction != ActionType.Attack && theirAllyAction != ActionType.Protect )
                    {
                        if( us.RoleProfile.Traits.Contains( RoleTrait.PriorityBlockAbility ) && theirAlly.Ability == AbilityID.Prankster )
                            costRisk += 1;

                        if( usIP.WeCan.FakeOut )
                            costRisk += 1;
                    }

                    foreach( var spe in candidate.RelevantPressures )
                    {
                        if( spe.Pressure == StrategyPressure.WeatherChange && usIP.WeCan.SetMoveWeather )
                            costRisk += 1;

                        if( spe.Pressure == StrategyPressure.TerrainChange && usIP.WeCan.SetMoveTerrain )
                            costRisk += 1;

                        if( ( spe.Pressure == StrategyPressure.GuaranteeRemoval || spe.Pressure == StrategyPressure.ImmediateRemoval ) && usIP.WeCan.Protect )
                            costRisk += 1;
                    }
                }

                int finalScore = pressureFit + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    DefensiveAlignment = defensiveAlignment,
                    OffensiveAlignment = offensiveAlignment,

                    PressureFitScore = pressureFit,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                if( defensiveAlignment > offensiveAlignment )
                    candidate.ChangeActionType( ActionType.DefensiveSwitch );
                else if( offensiveAlignment > defensiveAlignment )
                    candidate.ChangeActionType( ActionType.OffensiveSwitch );
                else
                    candidate.ChangeActionType( ActionType.DefensiveSwitch );

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSetupResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = _ai.GetRemainingPartyAs_IBattleAIUnits( theirActive[0].Pokemon ).Where( u => !theirActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var capabilitySets = ExtractUniqueCapabilities( ActionType.Setup, unit.Pokemon, pressureSets );

            if( capabilitySets?.Count <= 0 )
                continue;

            //--extract unique capabilities who have hashsets of pressures they are a response to.
            //--then, in  pressure fit, we can do score += coveredPressures.Count, naturally letting a response capability
            //--cover multiple options at once and rewarding it for doing so.
            foreach( var kvp in capabilitySets )
            {
                var capability = kvp.Key;
                var pressures = kvp.Value;

                foreach( var opp in theirActive )
                {
                    var candidate = GetSetupCandidate( capability, unit, opp, CoordinationActionType.Response );
                    candidate.RelevantPressures = pressures;
                    candidates.Add( candidate );
                }
            }

            foreach( var candidate in candidates )
            {
                int pressureFit = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );
                var ourSwitch = _ai.GetPokemonAs_IBattleAIUnit( candidate.SwitchCandidate );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var ourSwitchSP = _ai.Projection.GetStrategicProfile( ourSwitch );
                var theirSP = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                //--Pressure Fit
                pressureFit += candidate.RelevantPressures.Count;
                //--Candidate x Pressure family relevance goes here

                foreach( var e in candidate.RelevantPressures )
                {
                    var usIP = GetInteractionProfile( us, them, candidate, e );
                    var turnOrder = usIP.TurnOrder;

                    CoordinationAction switchCandidate = new()
                    {
                        Type = CoordinationActionType.SwitchCandidatePotential,
                        Actor = ourSwitch.Pokemon,
                        ActionType = ActionType.Attack,
                    };

                    var ourSwitchIP = GetInteractionProfile( ourSwitch, them, switchCandidate, e );

                    var ourPTKO = usIP.AttackerPTKO;
                    var ourSwitchPTKO = ourSwitchIP.AttackerPTKO;

                    var theirPTKO_Us = usIP.TargetPTKO;
                    var theirPTKO_OurSwitch = ourSwitchIP.TargetPTKO;

                    var theirAction = usIP.TheirAction;

                    bool theyUseAMove = theirAction != ActionType.OffensiveSwitch && theirAction != ActionType.DefensiveSwitch;
                    bool theySwitch = !theyUseAMove;

                    var theirMove = theyUseAMove && usIP.TheirActionResult.Move != null ? usIP.TheirActionResult.Move : null;
                    List<IBattleAIUnit> targetsTargets = usIP.TheirActionResult.Targets != null && usIP.TheirActionResult.Targets.Count > 0 ? usIP.TheirActionResult.Targets : null;
                    bool theyTargetUs = targetsTargets != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                    SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)usIP.TheirActionResult : default;
                    var theirSwitchCandidate = theySwitch ? scr.Candidate : null;
                    var usVsSwitch = theySwitch && theirSwitchCandidate != null ? _ai.Projection.MakeUnitComparison( us, theirSwitchCandidate ) : default;

                    bool weHaveAlly = TryGetAlly( us.Pokemon, out var ourAlly );
                    bool theyHaveAlly = TryGetOpponentAlly_FromStrategy( them.Pokemon, e, out IBattleAIUnit theirAlly );

                    bool targetsOurAlly = weHaveAlly && ourAlly != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == ourAlly.Pokemon );

                    bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );
                    bool theirAllyCanProtect = theyHaveAlly && theirAlly != null && _ai.CanUseProtect( theirAlly.Pokemon );

                    bool theirAllyHasIntent = TryGetOpponentAllyIntent_FromStrategy( them.Pokemon, e, out Intent theirAllyIntent );
                    var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                    var ourAllyVsThem = weHaveAlly ? _ai.Projection.MakeUnitComparison( ourAlly, them ) : default;
                    var usVsTheirAlly = theyHaveAlly ? _ai.Projection.MakeUnitComparison( us, theirAlly ) : default;
                    var ourAllyVsTheirAlly = theyHaveAlly && weHaveAlly ? _ai.Projection.MakeUnitComparison( ourAlly, theirAlly ) : default;
                    var ourSwitchVsTheirAlly = theyHaveAlly ? _ai.Projection.MakeUnitComparison( ourSwitch, theirAlly ) : default;

                    bool theyHavePrankster = them.Ability == AbilityID.Prankster;
                    bool theyAreUsingPrankster = theyUseAMove && theirMove != null && theirMove.MoveSO.MoveCategory == MoveCategory.Status;
                    bool theirPranksterIsOffensive = theyAreUsingPrankster && theirAction == ActionType.OffensiveStatus;
                    bool theirMoveHasPriority = theyUseAMove && theirMove != null && theirMove.Priority > MovePriority.Zero;

                    ActionType theirAllyAction = ActionType.Attack;
                    IActionResult theirAllyActionResult = default;
                    Move theirAllyMove = null;

                    PotentialToKO ourAllyPTKO_Them = ourAllyVsThem.Attacker.BestCurrentPTKO;
                    PotentialToKO ourAllyPTKO_TheirAlly = ourAllyVsTheirAlly.Attacker.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_Us = usVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_OurAlly = ourAllyVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_OurSwitch = ourSwitchVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirPTKO_OurAlly = ourAllyVsThem.Target.BestCurrentPTKO;

                    bool theirAllyUsesMove = false;
                    bool theirAllyHasPrankster = theyHaveAlly && theirAlly.Ability == AbilityID.Prankster;
                    bool theirAllyIsUsingPrankster = false;
                    bool theirAllyPranksterIsOffensive = false;
                    bool theirAllyMoveHasPriority = false;

                    bool theirAllyTargetsUs = false;
                    bool theirAllyTargetsOurAlly = false;

                    if( theirAllyHasIntent )
                    {
                        theirAllyAction = theirAllyIntent.IntentResult.ActionType;
                        theirAllyActionResult = theirAllyIntent.IntentResult;
                        
                        theirAllyUsesMove = theirAllyAction != ActionType.DefensiveSwitch && theirAllyAction != ActionType.OffensiveSwitch;
                        theirAllyMove = theirAllyUsesMove && theirAllyActionResult.Move != null ? theirAllyActionResult.Move : null;

                        theirAllyIsUsingPrankster = theirAllyHasPrankster && theirAllyUsesMove && theirAllyMove.MoveSO.MoveCategory == MoveCategory.Status;
                        theirAllyPranksterIsOffensive = theirAllyIsUsingPrankster && theirAllyAction == ActionType.OffensiveStatus;
                        theirAllyMoveHasPriority = theirAllyUsesMove && theirAllyMove.Priority > MovePriority.Zero;

                        if( weHaveAlly )
                        {
                            if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets[0]?.Pokemon == us.Pokemon )
                                theirAllyTargetsUs = true;
                            // else if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets[0]?.Pokemon == ourAlly.Pokemon )
                                // theirAllyTargetsOurAlly = true;

                            if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 1 && theirAllyActionResult.Targets[1]?.Pokemon == us.Pokemon )
                                theirAllyTargetsUs = true;

                            // if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 1 && theirAllyActionResult.Targets[1]?.Pokemon == ourAlly.Pokemon )
                                // theirAllyTargetsOurAlly = true;
                        }
                    }

                    //--Board Fit
                    if( mainCapability == CapabilityObservation.Substitute )
                    {
                        if( theyTargetUs )
                        {
                            if( theirAction == ActionType.OffensiveStatus && MovesBefore( us, them, turnOrder ) /*( them.Ability != AbilityID.Prankster && us.Speed > them.Speed )*/ )
                                boardFit += 1;
                            else
                                boardFit -= 1;

                            if( theirPTKO_Us <= PotentialToKO.Sturdy )
                                boardFit += 1;
                        }

                        if( theirAction == ActionType.DefensiveSwitch || theirAction == ActionType.OffensiveSwitch )
                            boardFit += 1;

                        if( theirAllyTargetsUs )
                        {
                            if( theirAllyAction == ActionType.OffensiveStatus && MovesBefore( us, them, turnOrder ) /*( theirAlly?.Ability != AbilityID.Prankster && us.Speed > them.Speed )*/ )
                                boardFit += 1;
                            else
                                boardFit -= 1;

                            if( theirAllyPTKO_Us <= PotentialToKO.Sturdy )
                                boardFit += 1;
                        }

                        if( theyTargetUs && theirAllyTargetsUs && !usIP.WeCan.Protect )
                            boardFit += 1;

                        if( us.BeginningHPR <= 0.5f && ( theirPTKO_Us >= PotentialToKO.TwoHKO || theirAllyPTKO_Us >= PotentialToKO.TwoHKO ) )
                            boardFit -= 2;
                    }

                    int atkBoosts = 0;
                    int spAtkBoosts = 0;
                    int defBoosts = 0;
                    int spDefBoosts = 0;
                    int speedBoosts = 0;
                    int totalBoosts = 0;

                    if( mainCapability == CapabilityObservation.StatBoost )
                    {
                        if( theyTargetUs )
                        {
                            if( theirAction == ActionType.Attack && theirPTKO_Us <= PotentialToKO.TwoHKO )
                                boardFit += 1;
                            else
                                boardFit -= 1;

                            bool fasterTaunt = theirMove?.MoveSO.Name == "Taunt" && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                            if( theirAction == ActionType.OffensiveStatus && ( fasterTaunt || theirMove?.MoveSO.Name == "Encore" ) )
                                boardFit -= 2;
                        }

                        if( theirAllyTargetsUs )
                        {
                            if( theirAllyAction == ActionType.Attack && theirAllyPTKO_Us <= PotentialToKO.TwoHKO )
                                boardFit += 1;
                            else
                                boardFit -= 1;

                            bool fasterTaunt = theirAllyMove?.MoveSO.Name == "Taunt" && ( theirAlly?.Ability == AbilityID.Prankster || theirAlly?.Speed > us.Speed );
                            if( theirAction == ActionType.OffensiveStatus && ( fasterTaunt || theirAllyMove?.MoveSO.Name == "Encore" ) )
                                boardFit -= 2;
                        }

                        var setupMove = candidate.MoveCandidate;
                        if( setupMove != null && setupMove.MoveEffects.StatChangeList != null && setupMove.MoveEffects.StatChangeList.Count > 0 )
                        {
                            foreach( var sc in setupMove.MoveEffects.StatChangeList )
                            {
                                if( sc.Stat == Stat.Attack && sc.Change > 0 )
                                    atkBoosts += sc.Change;

                                if( sc.Stat == Stat.SpAttack && sc.Change > 0 )
                                    spAtkBoosts += sc.Change;

                                if( sc.Stat == Stat.Defense && sc.Change > 0 )
                                    defBoosts += sc.Change;

                                if( sc.Stat == Stat.SpDefense && sc.Change > 0 )
                                    spDefBoosts += sc.Change;

                                if( sc.Stat == Stat.Speed && sc.Change > 0 )
                                    speedBoosts += sc.Change;
                            }

                            totalBoosts = atkBoosts + spAtkBoosts + defBoosts + spDefBoosts + speedBoosts;
                            int newSpeed = Mathf.FloorToInt( us.Speed * _stageModifier[speedBoosts] );

                            if( newSpeed > them.Speed )
                            {
                                boardFit += 1;

                                if( them.Speed > us.Speed )
                                    boardFit += 1;
                            }

                            if( newSpeed > theirAlly?.Speed )
                            {
                                boardFit += 1;

                                if( theirAlly?.Speed > us.Speed )
                                    boardFit += 1;
                            }

                            if( theyTargetUs && theirMove?.MoveSO.MoveCategory != MoveCategory.Status )
                            {
                                Stat attackStat = theirMove?.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;

                                if( ( attackStat == Stat.Attack && defBoosts > 0 ) || ( attackStat == Stat.SpAttack && spDefBoosts > 0 ) )
                                {
                                    Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                    var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                    var theirEDR = theirMTR.EDR;

                                    Dictionary<Stat, int> statChanges = new();

                                    if( defenseStat == Stat.Defense )
                                        statChanges.Add( Stat.Defense, defBoosts );
                                    else if( defenseStat == Stat.SpDefense )
                                        statChanges.Add( Stat.SpDefense, spDefBoosts );
                                    
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, targetStatStageChanges: statChanges );

                                    if( adjustedPTKO < theirPTKO_Us )
                                        boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                        boardFit += 1;
                                }
                            }

                            if( theirAllyTargetsUs && theirAlly != null && theirAllyMove?.MoveSO.MoveCategory != MoveCategory.Status )
                            {
                                Stat attackStat = theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;

                                if( ( attackStat == Stat.Attack && defBoosts > 0 ) || ( attackStat == Stat.SpAttack && spDefBoosts > 0 ) )
                                {
                                    Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                    var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                    var theirAllyEDR = theirAllyMTR.EDR;

                                    Dictionary<Stat, int> statChanges = new();

                                    if( defenseStat == Stat.Defense )
                                        statChanges.Add( Stat.Defense, defBoosts );
                                    else if( defenseStat == Stat.SpDefense )
                                        statChanges.Add( Stat.SpDefense, spDefBoosts );
                                    
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, targetStatStageChanges: statChanges );

                                    if( adjustedPTKO < theirPTKO_Us )
                                        boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                        boardFit += 1;
                                }
                            }
                        }
                    }

                    if( weHaveAlly )
                    {
                        if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) )
                            boardFit += 1;

                        if( ( theyTargetUs && _ai.CanUseFakeOut( ourAlly, them ) ) || ( theirAlly != null && theirAllyTargetsUs && _ai.CanUseFakeOut( ourAlly, theirAlly ) ) )
                            boardFit += 1;
                    }

                    //--Unit Fit
                    if( mainCapability == CapabilityObservation.Substitute )
                    {
                        if( us.BeginningHPR >= 0.7f )
                            unitFit += 1;

                        if( us.RoleProfile.Traits.Contains( RoleTrait.StatBooster ) || us.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) || us.RoleProfile.Biases.Contains( RoleBias.Disruptive ) )
                            unitFit += 1;

                        if( theyTargetUs && theirPTKO_Us <= PotentialToKO.Sturdy && ourPTKO >= PotentialToKO.Risky )
                            unitFit += 1;

                        if( theirAllyTargetsUs && theirAllyPTKO_Us <= PotentialToKO.Sturdy && ourPTKO >= PotentialToKO.Risky )
                            unitFit += 1;

                        if( ( !theyTargetUs && theirAllyTargetsUs ) || ( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) ) )
                            unitFit += 1;
                    }

                    if( mainCapability == CapabilityObservation.StatBoost )
                    {
                        var setupMove = candidate.MoveCandidate;

                        if( us.RoleProfile.Biases.Contains( RoleBias.Physical ) && atkBoosts > 0 )
                            unitFit += 1;

                        if( us.RoleProfile.Biases.Contains( RoleBias.Special ) && spAtkBoosts > 0 )
                            unitFit += 1;

                        if( us.RoleProfile.Biases.Contains( RoleBias.PhysicallyBulky ) && defBoosts > 0 )
                            unitFit += 1;

                        if( us.RoleProfile.Biases.Contains( RoleBias.SpeciallyBulky ) && spDefBoosts > 0 )
                            unitFit += 1;

                        if( defBoosts > 0 && us.Pokemon.CheckHasActiveMove( "Body Press" ) )
                            unitFit += 1;

                        if( us.Pokemon.CheckHasActiveMove( "Stored Power" ) || us.Pokemon.CheckHasActiveMove( "Baton Pass" ) )
                        {
                            if( totalBoosts > 3 )
                                unitFit += 3;
                            else if( totalBoosts > 1 )
                                unitFit += 2;
                            else if( totalBoosts > 0 )
                                unitFit += 1;
                        }
                    }

                    //--Plan Fit
                    bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                    bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                    bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                    bool ourAllyIsWincon = ourAlly != null && ourAlly.Pokemon == gp.OurPrimaryWinCon;
                    bool ourAllyIsBlocker = ourAlly != null && gp.OurBlockers.Contains( ourAlly.Pokemon );
                    bool ourAllyIsEnabler = ourAlly != null && gp.OurEnablers.Contains( ourAlly.Pokemon );

                    bool theyHaveWincon = them.Pokemon == gp.TheirPrimaryWinCon || ( theirAlly != null && theirAlly.Pokemon == gp.TheirPrimaryWinCon );
                    bool theyHaveBlocker = gp.TheirBlockers.Contains( them.Pokemon ) || ( theirAlly != null && gp.TheirBlockers.Contains( theirAlly.Pokemon ) );
                    bool theyHaveEnabler = gp.TheirEnablers.Contains( them.Pokemon ) || ( theirAlly != null && gp.TheirEnablers.Contains( theirAlly.Pokemon ) );

                    if( mainCapability == CapabilityObservation.Substitute )
                    {
                        if( weAreWincon || weAreBlocker || weAreEnabler )
                            planFit += 1;

                        if( weAreWincon && ( theyHaveWincon || theyHaveBlocker || theyHaveEnabler ) )
                            planFit += 1;

                        if( weAreBlocker && theyHaveWincon )
                            planFit += 1;

                        if( ( weAreWincon && ourAllyIsEnabler ) || ( weAreEnabler && ourAllyIsWincon ) )
                            planFit += 1;
                    }

                    if( weAreWincon && ( atkBoosts > 0 || spAtkBoosts > 0 ) )
                    {
                        planFit += 1;

                        if( theyHaveWincon )
                            planFit += 1;

                        if( ourAllyIsEnabler )
                            planFit += 1;
                    }

                    if( weAreWincon && theyHaveBlocker && ( defBoosts > 0 || spDefBoosts > 0 ) )
                    {
                        planFit += 1;

                        if( ourAllyIsBlocker )
                            planFit += 1;

                        if( ourAllyIsEnabler )
                            planFit += 1;
                    }

                    if( weAreBlocker && theyHaveWincon && ( atkBoosts > 0 || defBoosts > 0 || spAtkBoosts > 0 || spDefBoosts > 0 ) )
                        planFit += 1;

                    if( weAreEnabler && speedBoosts > 0 )
                        planFit += 1;

                    //--Cost Risk
                    if( mainCapability == CapabilityObservation.Substitute )
                    {
                        if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                            costRisk += 1;

                        if( theyTargetUs && theirAllyTargetsUs )
                        {
                            if( MovesBefore( them, theirAlly, turnOrder ) /*them.Speed > theirAlly?.Speed*/ && theirPTKO_Us >= PotentialToKO.Safe && theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                                costRisk += 1;

                            if( MovesBefore( theirAlly, them, turnOrder) /*theirAlly?.Speed > them.Speed*/ && theirAllyPTKO_Us >= PotentialToKO.Safe && theirPTKO_Us >= PotentialToKO.Dangerous )
                                costRisk += 1;
                        }

                        if( us.BeginningHPR <= 0.75f )
                        {
                            costRisk += 1;

                            if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                                costRisk += 1;
                        }

                        if( them.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            costRisk += 1;

                        if( theirAlly != null && ( theirAlly.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) ) )
                            costRisk += 1;

                        if( ourPTKO >= PotentialToKO.Dangerous && ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                            costRisk += 1;
                    }

                    if( mainCapability == CapabilityObservation.StatBoost )
                    {
                        if( ourPTKO >= PotentialToKO.Dangerous && ( theirPTKO_Us <= PotentialToKO.TwoHKO || us.Speed > them.Speed ) )
                            costRisk += 1;

                        if( usVsTheirAlly.Attacker.BestCurrentPTKO >= PotentialToKO.Dangerous && ( theirAllyPTKO_Us <= PotentialToKO.TwoHKO || us.Speed > theirAlly?.Speed ) )
                            costRisk += 1;

                        if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Risky ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Risky ) )
                        {
                            if( usIP.WeCan.Protect )
                                costRisk += 1;

                            if( ourBench.Count > 0 )
                                costRisk += 1;
                        }

                        if( totalBoosts > 0 && ( ( us.Speed < them.Speed && theirPTKO_Us > PotentialToKO.TwoHKO ) || ( us.Speed < theirAlly?.Speed && theirAllyPTKO_Us > PotentialToKO.TwoHKO ) ) )
                            costRisk += 1;

                        if( them.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || them.RoleProfile.Traits.Contains( RoleTrait.Haze ) )
                            costRisk += 2;

                        if( theirAlly != null && ( theirAlly.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.Haze ) ) )
                            costRisk += 2;

                        bool theyFasterTaunt = them.RoleProfile.Traits.Contains( RoleTrait.Taunt ) && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                        bool theirAllyFasterTaunt = theirAlly != null && theirAlly.RoleProfile.Traits.Contains( RoleTrait.Taunt ) && ( theirAlly.Ability == AbilityID.Prankster || theirAlly.Speed > us.Speed );
                        bool theyFasterEncore = them.RoleProfile.Traits.Contains( RoleTrait.Encore ) && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                        bool theirAllyFasterEncore = theirAlly != null && theirAlly.RoleProfile.Traits.Contains( RoleTrait.Encore ) && ( theirAlly.Ability == AbilityID.Prankster || theirAlly.Speed > us.Speed );

                        if( theyFasterTaunt || theirAllyFasterTaunt )
                            costRisk += 1;

                        if( theyFasterEncore || theirAllyFasterEncore )
                            costRisk += 2;
                    }
                }

                int finalScore = pressureFit + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    PressureFitScore = pressureFit,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetOffensiveStatusResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = _ai.GetRemainingPartyAs_IBattleAIUnits( theirActive[0].Pokemon ).Where( u => !theirActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var capabilitySets = ExtractUniqueCapabilities( ActionType.OffensiveStatus, unit.Pokemon, pressureSets );

            if( capabilitySets?.Count <= 0 )
                continue;

            //--extract unique capabilities who have hashsets of pressures they are a response to.
            //--then, in  pressure fit, we can do score += coveredPressures.Count, naturally letting a response capability
            //--cover multiple options at once and rewarding it for doing so.
            foreach( var kvp in capabilitySets )
            {
                var capability = kvp.Key;
                var pressures = kvp.Value;

                foreach( var opp in theirActive )
                {
                    var candidate = GetOffensiveStatusCandidate( capability, unit, opp, CoordinationActionType.Response );
                    candidate.RelevantPressures = pressures;
                    candidates.Add( candidate );
                }
            }

            foreach( var candidate in candidates )
            {
                int pressureFit = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                bool statusEffect = false; //--eventually need to separate into severe status and volatile status for confusion and affection and such --08/18/26
                bool disruption = false;
                bool entryHazard = false;
                bool statDebuff = false;
                bool phaze = false;

                bool reflectable = candidate.MoveCandidate != null && candidate.MoveCandidate.MoveSO.Flags != null && candidate.MoveCandidate.MoveSO.Flags.Count > 0 && candidate.MoveCandidate.MoveSO.Flags.Contains( MoveFlags.Reflectable );
                bool theyReflect = candidate.Target?.AbilityID == AbilityID.MagicBounce;
                bool theyBlock = candidate.Target?.AbilityID == AbilityID.MagicGuard || candidate.Target?.AbilityID == AbilityID.GoodAsGold;

                if( theyBlock )
                    continue;

                if( reflectable && theyReflect )
                    continue;

                if( candidate.Actor.VolatileStatuses.ContainsKey( VolatileConditionID.Taunt ) )
                    continue;

                if( candidate.Actor?.AbilityID == AbilityID.Prankster && candidate.Target != null && candidate.Target.CheckTypes( PokemonType.Dark ) )
                    continue;

                switch( mainCapability )
                {
                    //--Status Effect
                    case CapabilityObservation.Wisp:
                    case CapabilityObservation.Hoarfrost:
                    case CapabilityObservation.Paralysis:
                    case CapabilityObservation.Sleep:
                    case CapabilityObservation.Toxic:
                        statusEffect = true;
                    break;

                    //--Disruption
                    case CapabilityObservation.Taunt:
                    case CapabilityObservation.Encore:
                    case CapabilityObservation.Disable:
                    case CapabilityObservation.Torment:
                    case CapabilityObservation.Imprison:
                    case CapabilityObservation.HealBlock:
                    case CapabilityObservation.PerishSong:
                        disruption = true;
                    break;

                    //--Entry Hazard
                    case CapabilityObservation.HazardSetting:
                        entryHazard = true;
                    break;

                    //--Stat Debuff
