                        if( mainCapability == CapabilityObservation.StatReset )
                        {
                            void ScoreStatStageReset( IBattleAIUnit unit, Move move, EstimatedDamageResult edr, Dictionary<Stat, int> statStages )
                            {
                                int atkBoosts = 0;
                                int defBoosts = 0;
                                int spatkBoosts = 0;
                                int spdefBoosts = 0;
                                int speBoosts = 0;

                                int atkDrops = 0;
                                int defDrops = 0;
                                int spatkDrops = 0;
                                int spdefDrops = 0;
                                int speDrops = 0;

                                foreach( var sc in statStages )
                                {
                                    var stat = sc.Key;
                                    var change = sc.Value;
                                    if( change > 0 )
                                    {
                                        switch( stat )
                                        {
                                            case Stat.Attack: atkBoosts += change; break;
                                            case Stat.Defense: defBoosts += change; break;
                                            case Stat.SpAttack: spatkBoosts += change; break;
                                            case Stat.SpDefense: spdefBoosts += change; break;
                                            case Stat.Speed: speBoosts += change; break;
                                        }
                                    }

                                    if( change < 0 )
                                    {
                                        switch( stat )
                                        {
                                            case Stat.Attack: atkDrops += change; break;
                                            case Stat.Defense: defDrops += change; break;
                                            case Stat.SpAttack: spatkDrops += change; break;
                                            case Stat.SpDefense: spdefDrops += change; break;
                                            case Stat.Speed: speDrops += change; break;
                                        }
                                    }
                                }

                                int totalBoosts = atkBoosts + defBoosts + spatkBoosts + spdefBoosts + speBoosts;
                                int totalDrops = atkDrops + defDrops + spatkDrops + spdefDrops + speDrops;

                                if( totalBoosts > 3 )
                                    boardFit += 3;
                                else if( totalBoosts > 1 )
                                    boardFit += 2;
                                else if( totalBoosts > 0 )
                                    boardFit += 1;

                                if( totalBoosts > 0 && MovesBefore( us, unit, ip.TurnOrder ) )
                                    boardFit += 2;

                                if( totalDrops > 2 )
                                    boardFit -= 2;
                                else if( totalDrops > 0 )
                                    boardFit -= 1;

                                if( totalDrops > 0 && MovesBefore( us, unit, ip.TurnOrder ) )
                                    boardFit -= 1;

                                Dictionary<Stat, int> resetStages = new();

                                if( ( atkBoosts > 0 && unit.RoleProfile.Biases.Contains( RoleBias.Physical ) ) || ( spatkBoosts > 0 && unit.RoleProfile.Biases.Contains( RoleBias.Special ) ) )
                                {
                                    boardFit += 1;

                                    if( unit.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                        boardFit += 1;

                                    bool physical = move.MoveSO.MoveCategory == MoveCategory.Physical && atkBoosts > 0;
                                    bool special = move.MoveSO.MoveCategory == MoveCategory.Special && spatkBoosts > 0;

                                    bool unitIsThem = unit == them && theyAttack && move != null && ( physical || special );
                                    bool unitIsTheirAlly = theyHaveAlly && unit == theirAlly && theirAllyAttacks && move != null && ( physical || special );

                                    PotentialToKO incomingPTKO = default;
                                    PotentialToKO adjustedPTKO = default;

                                    if( unitIsThem && theyTargetUs )
                                    {
                                        incomingPTKO = theirPTKO_Us;
                                        adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( edr, them, us, attackerStatStageChanges: resetStages, targetStatStageChanges: resetStages );
                                    }
                                    
                                    if( unitIsThem && theyTargetOurAlly && ourAlly != null )
                                    {
                                        incomingPTKO = theirPTKO_OurAlly;
                                        adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( edr, them, ourAlly, attackerStatStageChanges: resetStages, targetStatStageChanges: resetStages );
                                    }
                                    
                                    if( unitIsTheirAlly && theirAllyTargetsUs )
                                    {
                                        incomingPTKO = theirAllyPTKO_Us;
                                        var theirAllyEDR = ip.UsVsTheirAlly.Target.BestEDR;
                                        adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackerStatStageChanges: resetStages, targetStatStageChanges: resetStages );
                                    }
                                    
                                    if( unitIsTheirAlly && theirAllyTargetsOurAlly && ourAlly != null )
                                    {
                                        incomingPTKO = theirAllyPTKO_OurAlly;
                                        var theirAllyEDR = ip.OurAllyVsTheirAlly.Target.BestEDR;
                                        adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, ourAlly, attackerStatStageChanges: resetStages, targetStatStageChanges: resetStages );
                                    }

                                    if( incomingPTKO > adjustedPTKO )
                                    {
                                        boardFit += 1;
                                        weReducePTKO = true;
                                        weImproveOurField = true;

                                        if( theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;

                                        if( theirPTKO_Us >= PotentialToKO.Dangerous && adjustedPTKO <= PotentialToKO.Dangerous )
                                        {
                                            boardFit += 1;

                                            if( theirPTKO_Us == PotentialToKO.OHKO )
                                                boardFit += 1;

                                            if( adjustedPTKO <= PotentialToKO.Safe )
                                                boardFit += 1;
                                        }
                                    }
                                }

                                if( speBoosts > 0 )
                                {
                                    if( unit.Speed > us.Speed && us.Speed > unit.Speed / _stageModifier[-speBoosts] )
                                        boardFit += 2;

                                    if( unit.Speed > ourAlly?.Speed && ourAlly?.Speed > unit.Speed / _stageModifier[-speBoosts] )
                                        boardFit += 2;
                                }
                            }

                            var theirStatStages = them.StatStages;
                            var theirAllyStatStages = theirAlly?.StatStages;

                            if( theirStatStages?.Count > 0 )
                                ScoreStatStageReset( them, theirMove, theirEDR, theirStatStages );

                            if( theirAlly != null && theirAllyStatStages?.Count > 0 )
                                ScoreStatStageReset( theirAlly, theirAllyMove, default, theirAllyStatStages );

                        }

                        if( mainCapability == CapabilityObservation.Defog )
                        {
                            bool theyWantScreens = ip.TheyWant.SetReflect || ip.TheyWant.SetLightScreen || ip.TheyWant.SetAuroraVeil;

                            if( ( ip.TheyWant.SetEntryHazard || theyWantScreens ) && MovesBefore( them, us, ip.TurnOrder ) )
                                boardFit += 5;

                            foreach( var kvp in ourCourt )
                            {
                                var condition = kvp.Key;
                                if( condition == CourtConditionID.Spikes )
                                    boardFit += 1;

                                if( condition == CourtConditionID.ToxicSpikes )
                                    boardFit += 1;

                                if( condition == CourtConditionID.StealthRock )
                                    boardFit += 1;

                                if( condition == CourtConditionID.StickyWeb )
                                    boardFit += 1;

                                if( condition == CourtConditionID.LeechSeed )
                                    boardFit += 1;
                            }

                            foreach( var kvp in theirCourt )
                            {
                                var condition = kvp.Key;

                                if( condition == CourtConditionID.Reflect )
                                    boardFit += 1;

                                if( condition == CourtConditionID.LightScreen )
                                    boardFit += 1;

                                if( condition == CourtConditionID.AuroraVeil )
                                    boardFit += 1;

                                if( condition == CourtConditionID.SafeGuard )
                                    boardFit += 1;
                            }
                        }
                    }

                    if( weAlterTurnOrder )
                        boardFit += 1;

                    if( weReducePTKO )
                        boardFit += 1;

                    if( weImproveOurOffense )
                        boardFit += 1;

                    if( weImproveOurDefense )
                        boardFit += 1;

                    if( weImproveOurField )
                        boardFit += 2;

                    if( weReduceTheirField )
                        boardFit += 2;

                    //------------
                    //--Unit Fit--
                    //------------
                    if( us.Speed > them.Speed || us.Ability == AbilityID.Prankster )
                        unitFit += 1;

                    if( us.Speed > theirAlly?.Speed || ( theirAlly != null && us.Ability == AbilityID.Prankster ) )
                        unitFit += 1;

                    if( us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        unitFit += 1;

                    if( us.RoleProfile.Biases.Contains( RoleBias.SupportFocused ) )
                        unitFit += 1;

                    bool reusable = mainCapability == CapabilityObservation.SideStatBuff || mainCapability == CapabilityObservation.SideHeal || mainCapability == CapabilityObservation.AfterYou;
                    bool redirection = mainCapability == CapabilityObservation.Redirection;
                    if( redirection || ( ( us.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) || us.Ability == AbilityID.Prankster ) && reusable ) )
                        unitFit += 1;

                    if( us.Item == ItemBattleEffectID.FocusSash || ( us.Item != ItemBattleEffectID.None && us.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) ) )
                        unitFit += 1;

                    if( ourAlly != null && ( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) || _ai.CanUseFakeOut( ourAlly, them ) ) )
                        unitFit += 1;

                    //------------
                    //--Plan Fit--
                    //------------
                    bool theyAreWincon = them.Pokemon == gp.TheirPrimaryWinCon;
                    bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                    bool theyAreEnabler = gp.TheirEnablers.Contains( them.Pokemon );

                    bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                    bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                    bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                    bool ourAllyIsWincon = ourAlly?.Pokemon == gp.OurPrimaryWinCon;

                    if( theyAreWincon && ( weReducePTKO || weImproveOurOffense ) )
                        planFit += 1;

                    if( theyAreBlocker || theyAreEnabler )
                    {
                        if( weImproveOurDefense )
                            planFit += 1;
                        
                        if( weImproveOurField )
                            planFit += 1;

                        if( weReduceTheirField )
                            planFit += 1;
                    }

                    if( weAreBlocker )
                    {
                        planFit += 1;

                        if( weReducePTKO )
                            planFit += 1;

                        if( weImproveOurDefense )
                            planFit += 1;

                        if( weReduceTheirField )
                            planFit += 1;
                    }

                    if( weAreEnabler && ourAllyIsWincon )
                    {
                        planFit += 1;

                        if( weImproveOurOffense )
                            planFit += 1;

                        if( weImproveOurDefense )
                            planFit += 1;

                        if( weImproveOurField )
                            planFit += 1;
                    }

                    //-------------
                    //--Cost/Risk--
                    //-------------
                    bool weBlockPriority = ( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.PriorityBlockAbility ) ) || currentTerrain == TerrainID.Psychic;

                    if( !weReducePTKO && theyTargetUs && theirPTKO_Us >= PotentialToKO.Dangerous )
                        costRisk += 2;

                    if( !weReducePTKO && theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                        costRisk += 2;

                    if( !weReducePTKO && theyTargetUs && theirAllyTargetsUs )
                        costRisk += 2;

                    if( ip.TheyCan.Taunt )
                        costRisk += 1;

                    if( ip.TheyCan.Encore && MovesBefore( them, us, ip.TurnOrder ) )
                        costRisk += 1;

                    if( ip.TheyWant.Taunt && MovesBefore( us, them, ip.TurnOrder ) )
                        costRisk += 2;

                    if( ip.TheyWant.Disable && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        costRisk += 1;

                    if( ip.TheyWant.FakeOut && !weBlockPriority )
                        costRisk += 3;

                    if( ip.TheyWant.TWave && !us.RoleProfile.Traits.Contains( RoleTrait.ThunderWaveImmune ) )
                    {
                        costRisk += 1;

                        if( MovesBefore( them, us, ip.TurnOrder ) )
                            costRisk += 1;
                    }

                    if( ( ip.TheyWant.SleepPowder || ip.TheyWant.Spore ) && ( !us.RoleProfile.Traits.Contains( RoleTrait.PowderImmune ) || !us.RoleProfile.Traits.Contains( RoleTrait.SleepImmune ) ) )
                    {
                        costRisk += 1;

                        if( MovesBefore( them, us, ip.TurnOrder ) )
                            costRisk += 1;
                    }
                }

                int finalScore = pressureFit + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    PressureFitScore = pressureFit,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetProtectResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = _ai.GetRemainingPartyAs_IBattleAIUnits( theirActive[0].Pokemon ).Where( u => !theirActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var capabilitySets = ExtractUniqueCapabilities( ActionType.Protect, unit.Pokemon, pressureSets );

            if( capabilitySets?.Count <= 0 )
                continue;

            //--extract unique capabilities who have hashsets of pressures they are a response to.
            //--then, in  pressure fit, we can do score += coveredPressures.Count, naturally letting a response capability
            //--cover multiple options at once and rewarding it for doing so.
            foreach( var kvp in capabilitySets )
            {
                var capability = kvp.Key;
                var pressures = kvp.Value;

                foreach( var opp in theirActive )
                {
                    var candidate = GetProtectCandidate( capability, unit, opp, CoordinationActionType.Response );
                    candidate.RelevantPressures = pressures;
                    candidates.Add( candidate );
                }
            }

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int pressureFit = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var theirSP  = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                //----------------
                //--Pressure Fit--
                //----------------
                //--Capability's Pressure Coverage
                int pressureFitScore = candidate.RelevantPressures.Count;

                foreach( var e in candidate.RelevantPressures )
                {
                    var ip = GetInteractionProfile( us, them, candidate, e );
                    var ourPTKO_Them = ip.AttackerPTKO;

                    var theirPTKO_Us = ip.TargetPTKO;
                    var theirAction = ip.TheirAction;
                    var theirActionResult = ip.TheirActionResult;
                    var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                    var theirEDR = theirMTR != null ? theirMTR.EDR : default;
                    
                    var theirAllyAction = ip.TheirAllyAction;
                    var theirAllyActionResult = ip.TheirAllyActionResult;
                    bool theirAllyHasIntent = ip.TheirAllyHasIntent;

                    var ourAlly = ip.AttackerAlly;
                    var theirAlly = ip.TargetAlly;

                    bool weHaveAlly = ourAlly != null;
                    bool theyHaveAlly = theirAlly != null;

                    var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                    var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                    bool theyAttack = theirAction == ActionType.Attack;
                    bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                    bool theySetup = theirAction == ActionType.Setup;
                    bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                    bool theyProtect = theirAction == ActionType.Protect;

                    bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                    var theirMove = theirActionResult.Move;

                    bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                    bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                    bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                    bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                    bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                    bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                    var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                    bool theirAllyUsesMove = theirAllyMove != null;
                    bool theirAllyTargetsUs = theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                    bool theirAllyTargetsOurAlly = theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                    var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                    
                    SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                    var theirSwitch = theySwitch ? scr.Candidate : null;

                    bool theyHaveSwitch = theirSwitch != null;

                    bool ourAllyMayWantToSwitch = false;

                    HashSet<CapabilityObservation> benchCapabilities = new();
                    foreach( var set in pressureSets )
                    {
                        var spe = set.Value;
                        foreach( var kvp in spe.ResponseCapabilities )
                        {
                            var mon = kvp.Key;
                            if( ourActive.Any( u => u.Pokemon == mon ) )
                                continue;

                            // benchCapabilities.AddRange( kvp.Value );
                            foreach( var bc in kvp.Value )
                                benchCapabilities.Add( bc );
                        }
                    }

                    //-------------
                    //--Board Fit--
                    //-------------
                    if( mainCapability == CapabilityObservation.Protect && _ai.CanUseProtect( us.Pokemon ) )
                    {
                        var mn = candidate.MoveCandidate.MoveSO.Name;
                        bool protect = mn == "Protect" || mn == "Detect";
                        bool burningBulwark = mn == "Burning Bulwark";
                        bool banefulBunker = mn == "Baneful Bunker";
                        bool silkTrap = mn == "Silk Trap";
                        bool spikyShield = mn == "Spiky Shield";
                        bool kingsShield = mn == "Kings Shield";
                        bool obstruct = mn == "Obstruct";

                        bool blocksStatus = protect || banefulBunker || spikyShield;

                        if( ( theyAttack || ( blocksStatus && theirAction == ActionType.OffensiveStatus ) ) && theirMove != null )
                        {
                            boardFit += 1;
                            
                            bool theyMoveFirst = ( theyAttack && !ip.UsVsThem.AttackerMovesFirst ) || ( theirAction == ActionType.OffensiveStatus && them.Ability == AbilityID.Prankster );
                            bool theirAllyMovesFirst = theyHaveAlly && ( ( theirAllyAttacks && !ip.UsVsThem.AttackerMovesFirst ) || ( theirAllyHasIntent && theirAllyAction == ActionType.OffensiveStatus && theirAlly?.Ability == AbilityID.Prankster ) );
                            
                            if( theyTargetUs && theirPTKO_Us >= PotentialToKO.Dangerous && theyMoveFirst )
                                boardFit += 1;

                            if( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Dangerous && theirAllyMovesFirst )
                                boardFit += 1;

                            if( theyTargetUs && theirAllyTargetsUs )
                                boardFit += 2;

                            if( ip.TheyWant.FakeOut )
                            {
                                boardFit += 1;

                                if( us.Item == ItemBattleEffectID.FocusSash && us.BeginningHPR == 1f )
                                    boardFit += 1;
                            }

                            if( weHaveAlly )
                            {
                                bool ourAllyMayWantToHitAllAdjacent = false;
                                
                                int allySwitchesPressures = 0;
                                int allyAllAdjacentPressures = 0;

                                if( ourAlly?.BeginningHPR <= 0.45f )
                                    allySwitchesPressures++;

                                if( theirPTKO_OurAlly >= PotentialToKO.Risky )
                                {
                                    allySwitchesPressures++;

                                    if( theyTargetOurAlly )
                                        allySwitchesPressures++;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous && !_ai.CanUseProtect( ourAlly.Pokemon ) )
                                        allySwitchesPressures++;
                                }

                                if( theirAllyPTKO_OurAlly >= PotentialToKO.Risky )
                                {
                                    allySwitchesPressures++;

                                    if( theirAllyTargetsOurAlly )
                                        allySwitchesPressures++;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous && !_ai.CanUseProtect( ourAlly.Pokemon ) )
                                        allySwitchesPressures++;
                                }

                                if( benchCapabilities.Count > 1 )
                                    allySwitchesPressures++;

                                if( theyTargetOurAlly && theirAllyTargetsOurAlly )
                                    allySwitchesPressures++;

                                ourAllyMayWantToSwitch = allySwitchesPressures > 4;

                                if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack ) )
                                {
                                    bool ourAllyUsesAllAdjacent = ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent || ( theyHaveAlly && ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent );
                                    bool ourAllyBestBothIsAllAdjacent = theyHaveAlly && ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent && ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent;
                                    
                                    if( ourAllyUsesAllAdjacent )
                                    {
                                        allyAllAdjacentPressures++;

                                        if( !theyHaveAlly )
                                            allyAllAdjacentPressures++;
                                    }

                                    if( ourAllyBestBothIsAllAdjacent )
                                    {
                                        allyAllAdjacentPressures++;

                                        if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                            allyAllAdjacentPressures++;

                                        if( ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                            allyAllAdjacentPressures++;
                                    }

                                    ourAllyMayWantToHitAllAdjacent = allyAllAdjacentPressures > 2;
                                }

                                if( ourAllyMayWantToHitAllAdjacent )
                                    boardFit += 2;

                                if( ourAllyMayWantToSwitch )
                                    boardFit += 2;
                            }

                            bool theirMoveMakesContact = theirMove.MoveSO.Flags.Contains( MoveFlags.Contact );

                            //--Burning Bulwark
                            if( burningBulwark && theirMoveMakesContact && them.SevereStatus == SevereConditionID.None )
                            {
                                if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                    boardFit += 1;

                                if( theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                    boardFit += 1;
                            }

                            //--Baneful Bunker
                            if( burningBulwark && theirMoveMakesContact && them.SevereStatus == SevereConditionID.None )
                            {
                                boardFit += 2;
                            }

                            //--Silk Trap
                            if( silkTrap && theirMoveMakesContact )
                            {
                                boardFit += 1;

                                if( them.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) || them.RoleProfile.Biases.Contains( RoleBias.MiddlingSpeed ) )
                                    boardFit += 1;

                                if( them.Speed > us.Speed && us.Speed > them.Speed / _stageModifier[1] )
                                    boardFit += 2;
                            }

                            //--Spiky Shield
                            if( spikyShield && theirMoveMakesContact )
                            {
                                boardFit += 2;

                                if( them.Item == ItemBattleEffectID.FocusSash || them.Ability == AbilityID.Sturdy || them.Ability == AbilityID.Disguise )
                                    boardFit += 2;

                                if( them.BeginningHPR <= 0.2f )
                                    boardFit += 2;
                            }

                            //--Kings Shield
                            if( kingsShield )
                            {
                                if( us.Ability == AbilityID.StanceChange )
                                {
                                    boardFit += 2;

                                    if( them.Speed > us.Speed )
                                        boardFit += 1;
                                }

                                if( theirMoveMakesContact )
                                {
                                    boardFit += 1;

                                    if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                        boardFit += 1;

                                    if( theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                        boardFit += 1;

                                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                                    {
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackerStatStageChanges: new(){ { Stat.Attack, 1 } } );

                                        if( adjustedPTKO < theirPTKO_Us )
                                            boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO )
                                            boardFit += 1;
                                    }

                                    if( weHaveAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                    {
                                        var theirEDR_OurAlly = ip.OurAllyVsThem.Target.BestEDR;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR_OurAlly, them, ourAlly, attackerStatStageChanges: new(){ { Stat.Attack, 1 } } );

                                        if( adjustedPTKO < theirPTKO_OurAlly )
                                            boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO )
                                            boardFit += 1;
                                    }
                                }
                            }

                            //--Obstruct
                            if( obstruct && theirMoveMakesContact )
                            {
                                boardFit += 1;

                                if( them.RoleProfile.Biases.Contains( RoleBias.PhysicallyBulky ) )
                                    boardFit += 1;

                                var ourBestMove = ip.UsVsThem.Attacker.CurrentPTKOs.Keys.First();
                                var ourAllyBestMove = weHaveAlly ? ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : null;

                                if( ourBestMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                    boardFit += 1;

                                if( ourAllyBestMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                    boardFit += 1;

                                if( ourPTKO_Them <= PotentialToKO.Risky )
                                {
                                    var edr = ip.UsVsThem.Attacker.BestEDR;
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( edr, us, them, targetStatStageChanges: new(){ { Stat.Defense, -2 } } );

                                    if( adjustedPTKO > ourPTKO_Them )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }

                                if( weHaveAlly && ourAllyPTKO_Them <= PotentialToKO.Risky )
                                {
                                    var edr = ip.OurAllyVsThem.Attacker.BestEDR;
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( edr, them, ourAlly, targetStatStageChanges: new(){ { Stat.Defense, -2 } } );

                                    if( adjustedPTKO > ourAllyPTKO_Them )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;

                                    if( MovesBefore( them, ourAlly, ip.TurnOrder ) )
                                        boardFit += 1;
                                }
                            }
                        }
                    }

                    if( mainCapability == CapabilityObservation.WideGuard && weHaveAlly )
                    {
                        bool theyUseSpread = theyAttack && theirMove != null && _ai.UnitSim.MoveIsSpreadAttack( theirMove );
                        bool theirAllyUsesSpread = theirAllyHasIntent && theirAllyAttacks && theirAllyMove != null && _ai.UnitSim.MoveIsSpreadAttack( theirAllyMove );

                        bool theirBestBothIsSpread = theyUseSpread && theyTargetUs && theirPTKO_Us >= PotentialToKO.Dangerous && theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous;
                        bool theirAllyBestBothIsSpread = theirAllyHasIntent && _ai.UnitSim.MoveIsSpreadAttack( ip.UsVsTheirAlly.Target.CurrentPTKOs.Keys.First() ) && theirAllyPTKO_Us >= PotentialToKO.Dangerous && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsThem.Target.CurrentPTKOs.Keys.First() ) && theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous;

                        if( theyAttack && ( theyUseSpread || theirAllyUsesSpread ) )
                        {
                            boardFit += 1;
                            
                            bool theyMoveFirst = ( theyAttack && !ip.UsVsThem.AttackerMovesFirst ) || ( theirAction == ActionType.OffensiveStatus && them.Ability == AbilityID.Prankster );
                            bool theirAllyMovesFirst = theyHaveAlly && ( ( theirAllyAttacks && !ip.UsVsThem.AttackerMovesFirst ) || ( theirAllyHasIntent && theirAllyAction == ActionType.OffensiveStatus && theirAlly?.Ability == AbilityID.Prankster ) );
                            
                            if( theyUseSpread && theirPTKO_Us >= PotentialToKO.Dangerous && theyMoveFirst )
                                boardFit += 1;

                            if( theirAllyUsesSpread && theirAllyPTKO_Us >= PotentialToKO.Dangerous && theirAllyMovesFirst )
                                boardFit += 1;

                            if( theirBestBothIsSpread )
                                boardFit += 1;

                            if( theirAllyBestBothIsSpread )
                                boardFit += 1;

                            if( ourAlly.RoleProfile.PrimaryArchetype != RoleClassArchetype.Defensive )
                                boardFit += 1;

                            if( theyUseSpread && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                boardFit += 1;

                            if( theirAllyUsesSpread && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                boardFit += 1;

                            if( weHaveAlly )
                            {
                                bool ourAllyUsesAllAdjacent = ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent || ( theyHaveAlly && ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveTarget == MoveTarget.AllAdjacent );
                                int allySwitchesPressures = 0;

                                if( ourAlly?.BeginningHPR <= 0.45f )
                                    allySwitchesPressures++;

                                if( theirPTKO_OurAlly >= PotentialToKO.Risky )
                                {
                                    allySwitchesPressures++;

                                    if( theyTargetOurAlly )
                                        allySwitchesPressures++;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous && !_ai.CanUseProtect( ourAlly.Pokemon ) )
                                        allySwitchesPressures++;
                                }

                                if( theirAllyPTKO_OurAlly >= PotentialToKO.Risky )
                                {
                                    allySwitchesPressures++;

                                    if( theirAllyTargetsOurAlly )
                                        allySwitchesPressures++;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous && !_ai.CanUseProtect( ourAlly.Pokemon ) )
                                        allySwitchesPressures++;
                                }

                                if( benchCapabilities.Count > 1 )
                                    allySwitchesPressures++;

                                if( theyTargetOurAlly && theirAllyTargetsOurAlly )
                                    allySwitchesPressures++;

                                ourAllyMayWantToSwitch = allySwitchesPressures > 4;

                                if( ourAllyMayWantToSwitch )
                                    boardFit += 2;

                                if( ourAllyUsesAllAdjacent )
                                    boardFit += 2;
                            }
                        }
                    }

                    if( mainCapability == CapabilityObservation.QuickGuard )
                    {

                    }

                    if( mainCapability == CapabilityObservation.CraftyShield )
                    {

                    }

                    if( mainCapability == CapabilityObservation.MatBlock )
                    {

                    }

                    //------------
                    //--Unit Fit--
                    //------------
                    if( us.RoleProfile.PrimaryArchetype != RoleClassArchetype.Defensive )
                        unitFit += 1;

                    if( ourAllyPTKO_Them <= PotentialToKO.TwoHKO && theirPTKO_Us >= PotentialToKO.Dangerous && MovesBefore( us, them, ip.TurnOrder ) )
                        unitFit += 2;

                    if( ( us.BeginningHPR <= 0.5f || theirPTKO_Us >= PotentialToKO.Dangerous ) && weHaveAlly && ourAllyPTKO_Them >= PotentialToKO.Dangerous && theyTargetUs )
                        unitFit += 2;

                    if( us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility && weHaveAlly && ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                        unitFit += 1;

                    if( ourAllyMayWantToSwitch )
                    {
                        if( theyTargetUs )
                            unitFit += 1;

                        if( theirAllyTargetsUs )
                            unitFit += 1;
                    }

                    //------------
                    //--Plan Fit--
                    //------------
                    bool weAreWincon = gp.OurPrimaryWinCon == us.Pokemon;
                    bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                    bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                    bool theyThreatenUs = theirPTKO_Us >= PotentialToKO.Dangerous && MovesBefore( us, them, ip.TurnOrder );

                    if( weAreWincon && theyThreatenUs )
                        planFit += 1;

                    if( weAreEnabler && weHaveAlly && ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive && theyThreatenUs )
                        planFit += 1;

                    if( weAreBlocker && theyThreatenUs && weHaveAlly && ourAlly.Pokemon == gp.OurPrimaryWinCon )
                        planFit += 1;

                    //-------------
                    //--Cost/Risk--
                    //-------------
                    if( theyTargetUs && weHaveAlly && theirPTKO_Us >= PotentialToKO.Dangerous )
                        costRisk += 1;

                    if( theirAllyTargetsUs && weHaveAlly && theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                        costRisk += 1;

                    if( theirPTKO_Us <= PotentialToKO.Risky && ( ourPTKO_Them >= PotentialToKO.Risky || us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility ) )
                        costRisk += 1;

                    if( theyHaveAlly && theirAllyPTKO_Us <= PotentialToKO.Risky && ( ourAllyPTKO_TheirAlly >= PotentialToKO.Risky || us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility ) )
                        costRisk += 1;
                }

                int finalScore = pressureFit + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    PressureFitScore = pressureFit,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetAttackOpportunities( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon );

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon );

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();

            if( capabilitySets.TryGetValue( unit.Pokemon, out var monCapabilities ) )
            {
                foreach( var capability in monCapabilities )
                {
                    if( GetCapabilityActionType( capability ) != ActionType.Attack )
                        continue;

                    foreach( var opp in theirActive )
                    {
                        var candidate = GetAttackCandidate( capability, unit, opp, CoordinationActionType.Opportunity );
                        candidates.Add( candidate );
                    }
                }
            }

            if( candidates?.Count <= 0 )
                continue;

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int creations = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;
                var ourMove = candidate.MoveCandidate;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );

                var ip = GetInteractionProfile( us, them, candidate, null );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var theirSP  = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                var ourPTKO_Them = ip.AttackerPTKO;
                var theirPTKO_Us = ip.TargetPTKO;
                var attackerMovesFirst = ip.AttackerMovesFirst;

                var theirAction = ip.TheirAction;
                var theirActionResult = ip.TheirActionResult;
                var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                var theirEDR = theirMTR != null ? theirMTR.EDR : default;

                var theirAllyAction = ip.TheirAllyAction;
                var theirAllyActionResult = ip.TheirAllyActionResult;
                bool theirAllyHasIntent = ip.TheirAllyHasIntent;

                var ourAlly = ip.AttackerAlly;
                var theirAlly = ip.TargetAlly;

                bool weHaveAlly = ourAlly != null;
                bool theyHaveAlly = theirAlly != null;

                var asp = weHaveAlly ? GetAllySynergyProfile( us, ourAlly, them, candidate ) : default;

                var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                bool theyAttack = theirAction == ActionType.Attack;
                bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                bool theySetup = theirAction == ActionType.Setup;
                bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                bool theyProtect = theirAction == ActionType.Protect;

                bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                var theirMove = theirActionResult.Move;

                bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                bool theirAllyUsesMove = theyHaveAlly && theirAllyMove != null;
                bool theirAllyTargetsUs = theyHaveAlly && theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                bool theirAllyTargetsOurAlly = theyHaveAlly && theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                var ourPTKO_TheirAlly = theyHaveAlly ? ip.UsVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                var ourAllyMove_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : null;
                var ourAllyMove_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() : null;
                
                SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                var theirSwitch = theySwitch ? scr.Candidate : null;
                bool theyHaveSwitch = theirSwitch != null;
                var usVsSwitch = theyHaveSwitch && theirSwitch != null ? _ai.Projection.MakeUnitComparison( us, theirSwitch ) : default;

                List<IBattleAIUnit> targetsTargets = ip.TheirActionResult.Targets != null && ip.TheirActionResult.Targets.Count > 0 ? ip.TheirActionResult.Targets : null;
                bool targetsUs = targetsTargets != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );

                WeatherConditionID targetsWeather = WeatherConditionID.None;
                WeatherConditionID theirAllyWeather = WeatherConditionID.None;
                WeatherConditionID switchesWeather = WeatherConditionID.None;

                bool targetSetWeather = _ai.UnitSim.Pokemon_SetWeather( them.Pokemon, out targetsWeather, currentWeather );
                bool allySetWeather = theyHaveAlly && _ai.UnitSim.Pokemon_SetWeather( theirAlly?.Pokemon, out theirAllyWeather, currentWeather );
                bool switchChangesWeather = theyHaveSwitch && _ai.UnitSim.Switch_ChangesWeather( scr, out switchesWeather, null );

                TerrainID targetsTerrain = TerrainID.None;
                TerrainID theirAllyTerrain = TerrainID.None;
                TerrainID switchesTerrain = TerrainID.None;

                bool targetSetTerrain = _ai.UnitSim.Pokemon_SetTerrain( them.Pokemon, out targetsTerrain, currentTerrain );
                bool allySetTerrain = theyHaveAlly && _ai.UnitSim.Pokemon_SetTerrain( theirAlly?.Pokemon, out theirAllyTerrain, currentTerrain );
                bool switchChangesTerrain = theyHaveSwitch && _ai.UnitSim.Switch_ChangesTerrain( scr, out switchesTerrain, null );

                bool allyCanSevere = asp.AllyCan.Wisp || asp.AllyCan.Hoarfrost || asp.AllyCan.TWave || asp.AllyCan.StunSpore || asp.AllyCan.Toxic || asp.AllyCan.Poison || asp.AllyCan.SleepPowder || asp.AllyCan.Spore;
                bool allyCanDisrupt = asp.AllyCan.Taunt || asp.AllyCan.Encore || asp.AllyCan.Disable || asp.AllyCan.StatDebuff;
                bool allyCanCreateField = asp.AllyCan.SetTailwind || asp.AllyCan.SetTrickRoom || asp.AllyCan.SetReflect || asp.AllyCan.SetLightScreen || asp.AllyCan.SetAuroraVeil || asp.AllyCan.SetMoveWeather || asp.AllyCan.SetMoveTerrain;
                bool allyCanSelfSupport = asp.AllyCan.Substitute || asp.AllyCan.SelfSetup;
                bool allyCanSideSupport = asp.AllyCan.SideHeal || asp.AllyCan.SideSetup;
                bool allyCanProtect = asp.AllyCan.Protect;
                bool allyCanCreate = allyCanCreateField || allyCanSideSupport || allyCanSelfSupport;
                bool allyCanRedirect = asp.AllyCan.FollowMe || asp.AllyCan.RagePowder;
                bool allyCanFakeOut = asp.AllyCan.FakeOut;
                bool allyCanSetScreens = asp.AllyCan.SetReflect || asp.AllyCan.SetLightScreen || asp.AllyCan.SetAuroraVeil;

                //-------------
                //--Board Fit--
                //-------------
                bool weCanReduceTheirThreat = false;
                bool weCanEnableOurAlly = false;
                bool weCanCoverOurAlly = false;
                bool weCanThreatenBigDamageAcrossTheBoard = false;
                bool weCanThreatenUtilityPressure = false;
                bool weCanRemoveTheirResources = false;
                bool weCanCreateBoardAdvantage = false;
                bool targetHasReasonToProtect = false;
                bool targetHasReasonToSwitch = false;

                //--All attacks have one thing in common - they do damage
                //--So we should have a general "do damage" assessment block that isn't restricted to
                //--any particular capability
                //--and let the unique features or intentions of a particular capability
                //--have their own blocks to allow things to differentiate from each other
                if( ourPTKO_Them >= PotentialToKO.Dangerous )
                {
                    boardFit += 1;

                    if( MovesBefore( us, them, ip.TurnOrder ) )
                        boardFit += 1;

                    if( ourPTKO_Them >= PotentialToKO.OHKO )
                        boardFit += 1;
                }

                if( ourPTKO_Them >= PotentialToKO.Risky && theyHaveAlly && ourPTKO_TheirAlly >= PotentialToKO.Risky )
                    weCanThreatenBigDamageAcrossTheBoard = true;

                if( them.BeginningHPR <= 0.45f )
                    boardFit += 1;

                if( MovesBefore( us, them, ip.TurnOrder ) )
                    boardFit += 1;

                if( !ip.TheyCan.Protect )
                    boardFit += 1;

                if( theyHaveAlly && _ai.UnitSim.MoveIsSpreadAttack( ourMove ) && ourPTKO_TheirAlly >= PotentialToKO.Risky )
                {
                    boardFit += 1;

                    if( ourPTKO_Them >= PotentialToKO.Risky )
                    {
                        boardFit += 1;
                        weCanThreatenBigDamageAcrossTheBoard = true;
                    }
                }

                if( theirPTKO_Us >= PotentialToKO.Dangerous && MovesBefore( them, us, ip.TurnOrder ) )
                    boardFit -= 5;


                if( mainCapability == CapabilityObservation.StrongestAttack )
                {
                    //--this block in particular can add special weight toward doing good damage/taking KOs
                    //--and it's okay for it to double up on signals from the general attack block
                    //--the whole point of this capability is to simply do damage, and so it should also be reinforced
                    //--by the general idea of attacking, and not simply be limited to that

                    if( ourPTKO_Them >= PotentialToKO.Dangerous && MovesBefore( us, them, ip.TurnOrder ) )
                    {
                        boardFit += 1;

                        if( theyTargetUs && theirPTKO_Us >= PotentialToKO.Dangerous )
                            boardFit += 1;

                        if( theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                        {
                            boardFit += 2;

                            if( allyCanCreate )
                                boardFit += 1;
                        }
                    }

                    if( theyHaveAlly && theirAllyTargetsUs && MovesBefore( us, theirAlly, ip.TurnOrder ) && MovesBefore( us, them, ip.TurnOrder ) && theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                    {
                        boardFit += 1;

                        if( allyCanFakeOut || allyCanRedirect )
                            boardFit += 1;
                    }
                }

                
                if( mainCapability == CapabilityObservation.CoverageMove )
                {
                    //--this block isn't necessarily about taking a KO. it's about doing optimal damage to the potential switch
                    //--candidate on the opponent's side. are we able to take this opportunity to reduce the safety or meaningfulness
                    //--of their potential switch?

                    //--If they don't switch, is our coverage move still good into the current target?
                    if( ourPTKO_Them >= PotentialToKO.Risky )
                    {
                        boardFit += 1;

                        if( ourMove?.MoveSO.SecondaryMoveEffects != null )
                            boardFit += 1;

                        if( ourPTKO_Them >= PotentialToKO.Dangerous )
                            boardFit += 1;

                        if( MovesBefore( us, them, ip.TurnOrder ) )
                            boardFit += 1;
                    }

                    if( theyHaveSwitch )
                    {
                        var ourPTKO_TheirSwitch = usVsSwitch.Attacker.CurrentPTKOs[ourMove];
                        boardFit += 1;

                        if( ourPTKO_TheirSwitch >= PotentialToKO.TwoHKO )
                        {
                            boardFit += 1;

                            if( ourPTKO_TheirSwitch >= PotentialToKO.Dangerous )
                                boardFit += 2;

                            //--Extra insurance against not switching
                            if( ourPTKO_Them >= PotentialToKO.Risky )
                                boardFit += 1;
                        }

                        if( switchChangesTerrain || switchChangesWeather )
                            boardFit += 2;

                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.FullHPSave ) && theirSwitch.BeginningHPR == 1f )
                            boardFit += 1;

                        if( us.Speed > theirSwitch.Speed )
                            boardFit += 2;

                        if( theirSwitch.Pokemon.CheckHasActiveMove( "Eruption" ) || theirSwitch.Pokemon.CheckHasActiveMove( "Water Spout" ) )
                            boardFit += 2;

                        if( theirSwitch.BeginningHPR == 1f || theirSwitch.BeginningHPR <= 0.45f )
                            boardFit += 1;
                    }
                }

                if( mainCapability == CapabilityObservation.FakeOut && _ai.CanUseFakeOut( us, them ) )
                {
                    var fakeoutPTKO_Them = ourMove.MoveSO.Name == "Fake Out" ? ip.UsVsThem.Attacker.CurrentPTKOs[ourMove] : PotentialToKO.Untouchable;

                    weCanReduceTheirThreat = true;
                    boardFit += 1;

                    if( them.BeginningHPR == 1f && ( them.Item == ItemBattleEffectID.FocusSash || them.RoleProfile.Traits.Contains( RoleTrait.FullHPSave ) ) )
                    {
                        weCanRemoveTheirResources = true;
                        boardFit += 1;
                    }

                    if( targetCanProtect )
                        targetHasReasonToProtect = true;

                    if( ip.TheyCan.FakeOut && MovesBefore( us, them, ip.TurnOrder ) )
                        boardFit += 1;
                    else if( ip.TheyCan.FakeOut && MovesBefore( them, us, ip.TurnOrder ) && !us.RoleProfile.Traits.Contains( RoleTrait.FakeOutImmune ) )
                        boardFit -= 1;
                    else if( ip.TheyCan.RawSwitch )
                        boardFit -= 2;
                    else
                        boardFit += 1;

                    if( them.BeginningHPR <= 0.1f || fakeoutPTKO_Them >= PotentialToKO.OHKO )
                    {
                        boardFit += 2;
                        weCanThreatenUtilityPressure = true;
                    }

                    if( weHaveAlly )
                    {
                        if( asp.AllyCan.SetTailwind || asp.AllyCan.SetTrickRoom )
                        {
                            boardFit += 3;
                            weCanEnableOurAlly = true;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                            weCanCreateBoardAdvantage = true;
                        }

                        if( asp.AllyCan.SetReflect || asp.AllyCan.SetLightScreen || asp.AllyCan.SetAuroraVeil )
                        {
                            boardFit += 2;
                            weCanEnableOurAlly = true;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                            weCanCreateBoardAdvantage = true;
                        }

                        if( asp.AllyCan.SetMoveWeather || asp.AllyCan.SetMoveTerrain )
                        {
                            boardFit += 1;
                            weCanEnableOurAlly = true;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                            weCanCreateBoardAdvantage = true;
                        }

                        if( asp.AllyCan.SelfSetup || asp.AllyCan.Substitute || asp.AllyCan.SideSetup || asp.AllyCan.SideHeal )
                        {
                            boardFit += 2;
                            weCanEnableOurAlly = true;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                            weCanCreateBoardAdvantage = true;
                        }

                        if( allyCanSevere || allyCanDisrupt )
                        {
                            boardFit += 1;
                            weCanEnableOurAlly = true;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                            weCanCreateBoardAdvantage = true;
                        }

                        if( theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                        {
                            boardFit += 2;
                            weCanCoverOurAlly = true;
                            weCanThreatenUtilityPressure = true;
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.KnockOff && them.Item != ItemBattleEffectID.None )
                {
                    weCanThreatenUtilityPressure = true;

                    if( _ai.UnitSim.PokemonHasItem_Offensive( them ) )
                    {
                        boardFit += 1;
                        weCanReduceTheirThreat = true;
                        weCanCreateBoardAdvantage = true;
                    }

                    if( them.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) )
                    {
                        boardFit += 1;
                        weCanReduceTheirThreat = true;
                        weCanCreateBoardAdvantage = true;
                    }

                    if( them.Item == ItemBattleEffectID.AssaultVest )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;
                        weCanCreateBoardAdvantage = true;
                    }

                    if( them.Item == ItemBattleEffectID.Eviolite )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;
                        weCanCreateBoardAdvantage = true;
                    }

                    if( them.Item == ItemBattleEffectID.ChoiceScarf && MovesBefore( them, us, ip.TurnOrder ) )
                    {
                        boardFit += 1;

                        if( them.Speed / 2 < us.Speed )
                        {
                            boardFit += 1;
                            weCanRemoveTheirResources = true;
                            weCanCreateBoardAdvantage = true;
                        }
                    }
                    
                    if( TryExtractMoveFromPokemon( "Knock Off", us, out var knockOff ) )
                    {
                        var knockOffPTKO = ip.UsVsThem.Attacker.CurrentPTKOs[knockOff];

                        if( knockOffPTKO >= PotentialToKO.Dangerous )
                        {
                            boardFit += 1;
                            weCanReduceTheirThreat = true;
                            targetHasReasonToSwitch = true;
                        }
                    }

                    if( theySwitch && theyHaveSwitch && theirSwitch.Item != ItemBattleEffectID.None )
                    {
                        boardFit += 1;

                        if( _ai.UnitSim.PokemonHasItem_Offensive( theirSwitch ) )
                        {
                            boardFit += 1;
                            weCanReduceTheirThreat = true;
                            weCanRemoveTheirResources = true;
                        }

                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) )
                        {
                            boardFit += 1;
                            weCanReduceTheirThreat = true;
                            weCanRemoveTheirResources = true;
                        }
                        
                        if( TryExtractMoveFromPokemon( "Knock Off", us, out var knockOffVsSwitch ) )
                        {
                            var knockOffPTKO = usVsSwitch.Attacker.CurrentPTKOs[knockOffVsSwitch];

                            if( knockOffPTKO >= PotentialToKO.Dangerous )
                            {
                                boardFit += 1;
                                weCanReduceTheirThreat = true;
                                weCanRemoveTheirResources = true;
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.ThroatChop && them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                {
                    boardFit += 1;

                    weCanReduceTheirThreat = true;
                    weCanRemoveTheirResources = true;
                    weCanThreatenUtilityPressure = true;

                    if( them.Item == ItemBattleEffectID.ThroatSpray )
                        boardFit += 1;

                    if( MovesBefore( us, them, ip.TurnOrder ) && theirMove != null && theirMove.MoveSO.Flags.Contains( MoveFlags.Sound ) )
                    {
                        boardFit += 2;

                        if( them.Item == ItemBattleEffectID.ThroatSpray )
                            boardFit += 1;

                        if( TryExtractMoveFromPokemon( "Throat Chop", us, out var throatChop ) )
                        {
                            var throatChopPTKO = ip.UsVsThem.Attacker.CurrentPTKOs[throatChop];

                            if( throatChopPTKO <= PotentialToKO.Risky )
                                boardFit += 1;
                        }
                    }

                    if( weHaveAlly && ourAlly.VolatileStatuses.Contains( VolatileConditionID.Substitute ) )
                    {
                        boardFit += 1;

                        if( MovesBefore( us, them, ip.TurnOrder ) )
                            weCanCoverOurAlly = true;
                    }

                    if( us.VolatileStatuses.Contains( VolatileConditionID.Substitute ) )
                        boardFit += 1;
                }

                if( mainCapability == CapabilityObservation.BrickBreak || mainCapability == CapabilityObservation.PsychicFangs || mainCapability == CapabilityObservation.RagingBull )
                {
                    bool weHaveReflect = ourCourt.ContainsKey( CourtConditionID.Reflect );
                    bool weHaveLightScreen = ourCourt.ContainsKey( CourtConditionID.LightScreen );
                    bool weHaveAuroraVeil = ourCourt.ContainsKey( CourtConditionID.AuroraVeil );
                    bool weHaveAScreen = weHaveReflect || weHaveLightScreen || weHaveAuroraVeil;
                    bool weHaveDualScreens = weHaveReflect && weHaveLightScreen;

                    if( theirCourt.ContainsKey( CourtConditionID.Reflect ) )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;

                        if( weHaveAScreen || allyCanSetScreens )
                        {
                            boardFit += 1;
                            weCanEnableOurAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( weHaveDualScreens )
                                boardFit += 1;
                        }

                        if( weHaveAlly )
                        {
                            if( ourAllyMove_Them?.MoveSO.MoveCategory == MoveCategory.Physical )
                            {
                                var allyEDR = ip.OurAllyVsThem.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, them, removeModifier: SCREENS_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_Them )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, them, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }

                            if( theyHaveAlly && ourAllyMove_TheirAlly?.MoveSO.MoveCategory == MoveCategory.Physical )
                            {
                                var allyEDR = ip.OurAllyVsTheirAlly.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, theirAlly, removeModifier: SCREENS_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_TheirAlly )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, theirAlly, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirAllyPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }
                    }

                    if( theirCourt.ContainsKey( CourtConditionID.LightScreen ) )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;

                        if( weHaveAScreen || allyCanSetScreens )
                        {
                            boardFit += 1;
                            weCanEnableOurAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( weHaveDualScreens )
                                boardFit += 1;
                        }

                        if( weHaveAlly )
                        {
                            if( ourAllyMove_Them?.MoveSO.MoveCategory == MoveCategory.Special )
                            {
                                var allyEDR = ip.OurAllyVsThem.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, them, removeModifier: SCREENS_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_Them )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, them, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }

                            if( theyHaveAlly && ourAllyMove_TheirAlly?.MoveSO.MoveCategory == MoveCategory.Special )
                            {
                                var allyEDR = ip.OurAllyVsTheirAlly.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, theirAlly, removeModifier: SCREENS_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_TheirAlly )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, theirAlly, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirAllyPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }
                    }

                    if( theirCourt.ContainsKey( CourtConditionID.AuroraVeil ) )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;

                        if( weHaveAScreen || allyCanSetScreens )
                        {
                            boardFit += 1;
                            weCanEnableOurAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( weHaveDualScreens )
                                boardFit += 1;
                        }

                        if( weHaveAlly )
                        {
                            if( ourAllyMove_Them?.MoveSO.MoveCategory != MoveCategory.Status )
                            {
                                var allyEDR = ip.OurAllyVsThem.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, them, removeModifier: AURORA_VEIL_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_Them )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, them, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }

                            if( theyHaveAlly && ourAllyMove_TheirAlly?.MoveSO.MoveCategory != MoveCategory.Status )
                            {
                                var allyEDR = ip.OurAllyVsTheirAlly.Attacker.BestEDR;
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( allyEDR, us, theirAlly, removeModifier: AURORA_VEIL_MODIFIER );

                                if( adjustedPTKO < ourAllyPTKO_TheirAlly )
                                {
                                    boardFit += 1;
                                    weCanEnableOurAlly = true;

                                    if( MovesBefore( us, ourAlly, ip.TurnOrder ) && MovesBefore( ourAlly, theirAlly, ip.TurnOrder ) )
                                        boardFit += 2;
                                    else if( MovesBefore( us, ourAlly, ip.TurnOrder ) && theirAllyPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( adjustedPTKO >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.RapidSpin || mainCapability == CapabilityObservation.MortalSpin )
                {
                    if( ourCourt.ContainsKey( CourtConditionID.Spikes ) || ourCourt.ContainsKey( CourtConditionID.ToxicSpikes ) || ourCourt.ContainsKey( CourtConditionID.StealthRock ) || ourCourt.ContainsKey( CourtConditionID.StickyWeb ) || ourCourt.ContainsKey( CourtConditionID.LeechSeed ) )
                        boardFit += 3;

                    if( ourPTKO_Them >= PotentialToKO.TwoHKO )
                        boardFit += 1;

                    if( mainCapability == CapabilityObservation.MortalSpin && them.SevereStatus == SevereConditionID.None && !them.RoleProfile.Traits.Contains( RoleTrait.PoisonToxImmune ) )
                        boardFit += 1;

                    if( mainCapability == CapabilityObservation.RapidSpin && them.Speed > us.Speed && us.Speed * _stageModifier[1] > them.Speed )
                        boardFit += 1;
                }

                if( mainCapability == CapabilityObservation.TrapMove )
                {
                    if( them.RoleProfile.PrimaryRole == RoleClass.Pivot || them.RoleProfile.SecondaryRoles.Contains( RoleClass.Pivot ) )
                        boardFit += 2;

                    if( ourPTKO_Them >= PotentialToKO.TwoHKO )
                        boardFit += 1;

                    if( asp.AllyCan.PerishSong )
                        boardFit += 3;

                    if( them.BeginningHPR <= 0.33f )
                        boardFit += 2;
                    else if( them.BeginningHPR <= 0.66f )
                        boardFit += 1;

                    if( ourAllyPTKO_Them >= PotentialToKO.Risky )
                        boardFit += 1;
                }

                //-------------
                //--Creations--
                //-------------
                if( weCanReduceTheirThreat )
                    creations += 1;

                if( weCanEnableOurAlly )
                    creations += 1;

                if( weCanCoverOurAlly )
                    creations += 1;

                if( weCanThreatenBigDamageAcrossTheBoard )
                    creations += 1;

                if( weCanThreatenUtilityPressure )
                    creations += 1;

                if( weCanRemoveTheirResources )
                    creations += 1;

                if( weCanCreateBoardAdvantage )
                    creations += 1;

                if( targetHasReasonToProtect )
                    creations += 1;

                if( targetHasReasonToSwitch )
                    creations += 1;

                //------------
                //--Unit Fit--
                //------------
                switch( us.RoleProfile.PrimaryArchetype )
                {
                    case RoleClassArchetype.Offensive:

                        //--All attack capabilities are offensive tools and should be rewarded flatly here.
                        unitFit += 1;

                        if( ourPTKO_Them >= PotentialToKO.Dangerous && attackerMovesFirst )
                        {
                            unitFit += 2;

                            if( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove )
                                unitFit += 1;
                        }
                        else if( ourPTKO_Them >= PotentialToKO.Dangerous && theirPTKO_Us <= PotentialToKO.Risky )
                        {
                            unitFit += 1;

                            if( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove )
                                unitFit += 1;
                        }

                        if( weCanThreatenBigDamageAcrossTheBoard )
                            unitFit += 1;

                    break;

                    case RoleClassArchetype.Defensive:

                        if( mainCapability == CapabilityObservation.FakeOut )
                            unitFit += 1;

                        if( mainCapability == CapabilityObservation.KnockOff )
                        {
                            unitFit += 1;

                            if( ourPTKO_Them >= PotentialToKO.Risky )
                                unitFit += 1;

                            if( theirPTKO_Us <= PotentialToKO.TwoHKO && them.Item != ItemBattleEffectID.None )
                                unitFit += 1;
                        }

                        if( weCanCoverOurAlly || weCanReduceTheirThreat || weCanRemoveTheirResources )
                            unitFit += 1;

                    break;

                    case RoleClassArchetype.Utility:

                        if( mainCapability == CapabilityObservation.FakeOut )
                            unitFit += 1;

                        if( mainCapability == CapabilityObservation.KnockOff )
                            unitFit += 1;

                        if( mainCapability == CapabilityObservation.ThroatChop && theyUseAMove && theirMove.MoveSO.Flags.Contains( MoveFlags.Sound ) )
                            unitFit += 1;

                        if( weCanCoverOurAlly || weCanEnableOurAlly || weCanRemoveTheirResources )
                            unitFit += 1;

                        if( weCanCreateBoardAdvantage )
                            unitFit += 1;
                            
                    break;
                }

                //--Board Effect Compatability
                if( _ai.UnitSim.PokemonAbilityMatchesWeather( us.Pokemon, currentWeather ) )
                    unitFit += 1;

                switch( currentWeather )
                {
                    case WeatherConditionID.Sun:

                        if( ourMove.MoveType == PokemonType.Fire )
                            unitFit += 1;

                    break;

                    case WeatherConditionID.Rain:

                        if( ourMove.MoveType == PokemonType.Water )
                            unitFit += 1;

                    break;

                    case WeatherConditionID.Sand:

                        if( us.Ability == AbilityID.SandForce && ( ourMove.MoveType == PokemonType.Rock || ourMove.MoveType == PokemonType.Ground || ourMove.MoveType == PokemonType.Steel ) )
                            unitFit += 1;

                    break;

                    case WeatherConditionID.Snow:

                        if( ourMove.MoveType == PokemonType.Ice )
                            unitFit += 1;

                    break;
                }

                //------------
                //--Plan Fit--
                //------------
                bool targetIsTheirWincon = them.Pokemon == gp.TheirPrimaryWinCon;
                bool targetIsBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                bool targetIsEnabler = gp.TheirEnablers.Contains( them.Pokemon );
                bool targetIsGamePlanUnit = targetIsTheirWincon || targetIsBlocker || targetIsEnabler;

                bool ourAllyIsWincon = ourAlly?.Pokemon == gp.OurPrimaryWinCon;
                bool ourAllyIsBlocker = weHaveAlly && gp.OurBlockers.Contains( ourAlly.Pokemon );
                bool ourAllyIsEnabler = weHaveAlly && gp.OurEnablers.Contains( ourAlly.Pokemon );

                if( ourPTKO_Them >= PotentialToKO.Dangerous && targetIsGamePlanUnit )
                    planFit += 1;

                if( mainCapability == CapabilityObservation.FakeOut )
                {
                    if( targetIsTheirWincon && theirPTKO_Us >= PotentialToKO.Risky )
                        planFit += 1;

                    if( targetIsEnabler )
                        planFit += 1;

                    if( theyHaveAlly )
                    {
                        bool theirAllyIsWincon = theirAlly.Pokemon == gp.TheirPrimaryWinCon;
                        bool theirAllyIsEnabler = gp.TheirEnablers.Contains( theirAlly.Pokemon );

                        if( targetIsTheirWincon && theirAllyIsEnabler || theirAllyIsWincon && targetIsEnabler )
                            planFit += 1;
                    }
                }

                if( mainCapability == CapabilityObservation.KnockOff )
                {
                    if( targetIsGamePlanUnit && theirSP.DependsOnItem )
                        planFit += 1;
                }

                if( mainCapability == CapabilityObservation.ThroatChop )
                {
                    if( targetIsTheirWincon && them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                        planFit += 1;
                }

                if( ourAllyIsWincon && ( weCanEnableOurAlly || weCanCoverOurAlly ) )
                    planFit += 1;

                if( ourAllyIsBlocker && ( weCanThreatenUtilityPressure || weCanThreatenBigDamageAcrossTheBoard || weCanCreateBoardAdvantage ) )
                    planFit += 1;

                if( ourAllyIsEnabler && ( weCanCoverOurAlly || weCanEnableOurAlly || weCanThreatenBigDamageAcrossTheBoard || weCanCreateBoardAdvantage ) )
                    planFit += 1;

                //-------------
                //--Cost/Risk--
                //-------------
                if( ourPTKO_Them <= PotentialToKO.Risky && mainCapability != CapabilityObservation.FakeOut )
                    costRisk += 1;

                if( MovesBefore( them, us, ip.TurnOrder ) && theirPTKO_Us >= PotentialToKO.Dangerous )
                {
                    costRisk += 2;

                    if( gp.OurPrimaryWinCon == us.Pokemon || gp.OurBlockers.Contains( us.Pokemon ) || gp.OurEnablers.Contains( us.Pokemon ) )
                        costRisk += 1;

                    if( weHaveAlly )
                    {
                        costRisk += 1;

                        if( ourAllySP.DependsOnFastAlly )
                            costRisk += 1;

                        if( weCanEnableOurAlly || weCanCoverOurAlly )
                            costRisk += 1;
                    }

                    if( theirPTKO_Us == PotentialToKO.OHKO )
                        costRisk += 1;
                }
                else if( MovesBefore( them, us, ip.TurnOrder ) && ourPTKO_Them <= PotentialToKO.TwoHKO && mainCapability != CapabilityObservation.FakeOut && us.BeginningHPR == 1f && ( us.Item == ItemBattleEffectID.FocusSash || us.RoleProfile.Traits.Contains( RoleTrait.FullHPSave ) ) )
                    costRisk += 2;

                if( weHaveAlly && MovesBefore( them, us, ip.TurnOrder ) && MovesBefore( them, ourAlly, ip.TurnOrder ) && theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                {
                    costRisk += 2;

                    if( ourAllyIsWincon || ourAllyIsBlocker || ourAllyIsEnabler )
                        costRisk += 1;

                    if( ourSP.DependsOnFastAlly )
                        costRisk += 1;
                }

                if( ip.TheyCan.Protect && !_ai.UnitSim.MoveIsSpreadAttack( ourMove ) && ( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove ) && theyHaveAlly && ourPTKO_TheirAlly >= PotentialToKO.Dangerous )
                    costRisk += 1;

                int finalScore = creations + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    CreationScore = creations,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSwitchOpportunities( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon );

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon );

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();

            foreach( var switchCandidate in ourBench )
            {
                if( capabilitySets.TryGetValue( unit.Pokemon, out var monCapabilities ) )
                {
                    foreach( var capability in monCapabilities )
                    {
                        if( GetCapabilityActionType( capability ) != ActionType.DefensiveSwitch )
                            continue;

                        foreach( var opp in theirActive )
                        {
                            var candidate = GetSwitchCandidate( capability, unit, switchCandidate, opp, CoordinationActionType.Opportunity );
                            candidates.Add( candidate );
                        }
                    }
                }
            }

            if( candidates?.Count <= 0 )
                continue;

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int creations = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                int defensiveAlignment = 0;
                int offensiveAlignment = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );
                var ourSwitch = _ai.GetPokemonAs_IBattleAIUnit( candidate.SwitchCandidate );

                var ip = GetInteractionProfile( us, them, candidate, null );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var theirSP  = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;
                bool theyAreWincon = gp.TheirPrimaryWinCon == them.Pokemon;
                bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                bool theyAreEneabler = gp.TheirEnablers.Contains( them.Pokemon );
                var theirWincon = _ai.GetPokemonAs_IBattleAIUnit( gp.TheirPrimaryWinCon );

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                var ourPTKO_Them = ip.AttackerPTKO;
                var theirPTKO_Us = ip.TargetPTKO;
                var attackerMovesFirst = ip.AttackerMovesFirst;

                var theirAction = ip.TheirAction;
                var theirActionResult = ip.TheirActionResult;
                var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                var theirEDR = theirMTR != null ? theirMTR.EDR : default;

                var theirAllyAction = ip.TheirAllyAction;
                var theirAllyActionResult = ip.TheirAllyActionResult;
                bool theirAllyHasIntent = ip.TheirAllyHasIntent;
                var theirAllyMTR = theirAllyHasIntent && theirAllyActionResult is MoveThreatResult taresult ? taresult : null;
                var theirAllyEDR = theirAllyMTR != null ? theirAllyMTR.EDR : default;

                var ourAlly = ip.AttackerAlly;
                var theirAlly = ip.TargetAlly;

                bool weHaveAlly = ourAlly != null;
                bool theyHaveAlly = theirAlly != null;

                var asp = weHaveAlly ? GetAllySynergyProfile( us, ourAlly, them, candidate ) : default;

                var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                bool theyAttack = theirAction == ActionType.Attack;
                bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                bool theySetup = theirAction == ActionType.Setup;
                bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                bool theyProtect = theirAction == ActionType.Protect;

                bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                var theirMove = theirActionResult.Move;

                bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                bool theirAllyUsesMove = theyHaveAlly && theirAllyMove != null;
                bool theirAllyTargetsUs = theyHaveAlly && theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                bool theirAllyTargetsOurAlly = theyHaveAlly && theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                var ourPTKO_TheirAlly = theyHaveAlly ? ip.UsVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirAllyVsOurSwitch = theyHaveAlly ? _ai.Projection.MakeUnitComparison( theirAlly, ourSwitch ) : default;
                var theirAllyEDR_OurSwitch = theyHaveAlly && theirAllyMove != null ? GetEDROnSwitchCandidate( theirAlly, ourSwitch, theirAllyMove ) : default;
                var theirAllyPTKO_OurSwitch = theyHaveAlly && theirAllyMove != null ? _ai.Projection.GetPTKO_FromDamageEstimate( theirAllyEDR_OurSwitch, ourSwitch ) : PotentialToKO.Untouchable;
                
                var themVsOurSwitch = _ai.Projection.MakeUnitComparison( them, us );
                var theirEDR_OurSwitch = theirMove != null ? GetEDROnSwitchCandidate( them, ourSwitch, theirMove ) : default;
                var theirPTKO_OurSwitch = theirMove != null ? _ai.Projection.GetPTKO_FromDamageEstimate( theirEDR_OurSwitch, ourSwitch ) : PotentialToKO.Untouchable;

                var ourAllyMove_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : null;
                var ourAllyMove_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() : null;

                bool theyHavePrankster = them.Ability == AbilityID.Prankster;
                bool theyAreUsingPrankster = theyUseAMove && theirMove?.MoveSO.MoveCategory == MoveCategory.Status;
                bool theirPranksterIsOffensive = theyAreUsingPrankster && theirAction == ActionType.OffensiveStatus;
                bool theirMoveHasPriority = theyUseAMove && theirMove?.Priority > MovePriority.Zero;

                bool theirAllyHasPrankster = theyHaveAlly && theirAlly?.Ability == AbilityID.Prankster;
                bool theirAllyIsUsingPrankster = theirAllyUsesMove && theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Status;
                bool theirAllyPranksterIsOffensive = theirAllyIsUsingPrankster && theirAllyAction == ActionType.OffensiveStatus;
                bool theirAllyMoveHasPriority = theyHaveAlly && theirAllyUsesMove && theirAllyMove?.Priority > MovePriority.Zero;
                
                SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                var theirSwitch = theySwitch ? scr.Candidate : null;
                bool theyHaveSwitch = theirSwitch != null;
                var usVsSwitch = theyHaveSwitch && theirSwitch != null ? _ai.Projection.MakeUnitComparison( us, theirSwitch ) : default;

                List<IBattleAIUnit> targetsTargets = ip.TheirActionResult.Targets != null && ip.TheirActionResult.Targets.Count > 0 ? ip.TheirActionResult.Targets : null;
                bool targetsUs = targetsTargets != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );

                WeatherConditionID targetsWeather = WeatherConditionID.None;
                WeatherConditionID theirAllyWeather = WeatherConditionID.None;
                WeatherConditionID switchesWeather = WeatherConditionID.None;

                bool targetSetWeather = _ai.UnitSim.Pokemon_SetWeather( them.Pokemon, out targetsWeather, currentWeather );
                bool allySetWeather = theyHaveAlly && _ai.UnitSim.Pokemon_SetWeather( theirAlly?.Pokemon, out theirAllyWeather, currentWeather );
                bool switchChangesWeather = theyHaveSwitch && _ai.UnitSim.Switch_ChangesWeather( scr, out switchesWeather, null );

                TerrainID targetsTerrain = TerrainID.None;
                TerrainID theirAllyTerrain = TerrainID.None;
                TerrainID switchesTerrain = TerrainID.None;

                bool targetSetTerrain = _ai.UnitSim.Pokemon_SetTerrain( them.Pokemon, out targetsTerrain, currentTerrain );
                bool allySetTerrain = theyHaveAlly && _ai.UnitSim.Pokemon_SetTerrain( theirAlly?.Pokemon, out theirAllyTerrain, currentTerrain );
                bool switchChangesTerrain = theyHaveSwitch && _ai.UnitSim.Switch_ChangesTerrain( scr, out switchesTerrain, null );
                
                //--Current Unit switch-based capability preservations
                bool creationPreservationChance = false;
                foreach( var c in capabilitySets[unit.Pokemon] )
                {
                    if( GetCapabilityActionType( c ) != ActionType.DefensiveSwitch )
                        continue;

                    if( us.BeginningHPR <= 0.66f )
                        boardFit += 1;

                    if( mainCapability == CapabilityObservation.RawSwitch )
                    {
                        boardFit += 1;

                        if( asp.WeCan.SetTailwind && ourCourt.ContainsKey( CourtConditionID.Tailwind ) )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;
                        }

                        if( asp.WeCan.SetAbilityTerrain && _ai.UnitSim.GetTerrainFrom_Ability( us.Pokemon ) == currentTerrain )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;
                        }

                        if( asp.WeCan.SetAbilityWeather && _ai.UnitSim.GetWeatherFrom_Ability( us.Pokemon ) == currentWeather )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;
                        }
                    }

                    if( c == CapabilityObservation.Intimidate )
                    {
                        if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;

                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;
                        }

                        if( theyHaveAlly && theirAlly.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;

                            if( theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;
                        }

                        if( theirWincon.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                        {
                            boardFit += 1;

                            if( theyAreWincon )
                                boardFit += 1;
                        }
                    }

                    if( c == CapabilityObservation.Demoralize )
                    {
                        if( them.RoleProfile.Biases.Contains( RoleBias.Special ) )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;

                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;
                        }

                        if( theyHaveAlly && theirAlly.RoleProfile.Biases.Contains( RoleBias.Special ) )
                        {
                            boardFit += 1;
                            creationPreservationChance = true;

                            if( theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;
                        }

                        if( theirWincon.RoleProfile.Biases.Contains( RoleBias.Special ) )
                        {
                            boardFit += 1;

                            if( theyAreWincon )
                                boardFit += 1;
                        }
                    }

                    if( c == CapabilityObservation.WeatherSetAbility )
                    {
                        creationPreservationChance = true;

                        if( _ai.UnitSim.GetWeatherFrom_Ability( us.Pokemon ) == currentWeather )
                        {
                            boardFit += 1;

                            if( ip.TheyCan.SetAbilityWeather )
                                boardFit += 1;

                            if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.WeatherSetter ) )
                                boardFit += 1;
                        }

                        if( ip.TheyCan.SetAbilityWeather && _ai.UnitSim.GetWeatherFrom_Ability( them.Pokemon ) == currentWeather )
                        {
                            boardFit += 2;

                            if( currentWeather == WeatherConditionID.Sun )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                                    boardFit += 1;
                            }

                            if( currentWeather == WeatherConditionID.Rain )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                                    boardFit += 1;
                            }

                            if( currentWeather == WeatherConditionID.Sand )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                                    boardFit += 1;
                            }

                            if( currentWeather == WeatherConditionID.Snow )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                                    boardFit += 1;
                            }
                        }
                    }

                    if( c == CapabilityObservation.TerrainSetAbility )
                    {
                        creationPreservationChance = true;

                        if( _ai.UnitSim.GetTerrainFrom_Ability( us.Pokemon ) == currentTerrain )
                        {
                            boardFit += 1;

                            if( ip.TheyCan.SetAbilityWeather )
                                boardFit += 1;

                            if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.WeatherSetter ) )
                                boardFit += 1;
                        }

                        if( ip.TheyCan.SetAbilityWeather && _ai.UnitSim.GetTerrainFrom_Ability( them.Pokemon ) == currentTerrain )
                        {
                            boardFit += 2;

                            if( currentTerrain == TerrainID.Blighted )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainAbuser ) )
                                    boardFit += 1;
                            }

                            if( currentTerrain == TerrainID.Electric )
                            {
                                if( them.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainAbuser ) )
                                    boardFit += 1;

                                if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainAbuser ) )
                                    boardFit += 1;
