                                    if( MovesBefore( theirAlly, ourAlly, ip.TurnOrder ) && adjustedPTKO <= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                    {
                                        boardFit += 2;
                                        offensiveAlignment++;
                                        weCanEnableAlly = true;
                                    }
                                    else if( adjustedPTKO <= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                    {
                                        boardFit += 3;
                                        offensiveAlignment++;
                                        weCanEnableAlly = true;
                                    }
                                }
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.Demoralize )
                {
                    if( them.RoleProfile.Biases.Contains( RoleBias.Special ) )
                        boardFit += 1;

                    if( theyUseAMove && theirMove?.MoveSO.MoveCategory == MoveCategory.Special )
                    {
                        defensiveAlignment++;

                        boardFit += 1;

                        if( targetsUs )
                            boardFit += 1;

                        if( weHaveAlly && !targetsUs )
                            boardFit += 1;

                        Dictionary<Stat, int> demoralize = new(){ { Stat.SpAttack, -1 } };

                        if( targetsUs )
                        {
                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR_OurSwitch, them, ourSwitch, attackerStatStageChanges: demoralize );

                            if( adjustedPTKO < theirPTKO_OurSwitch )
                            {
                                ourSwitchCanEnterSafely = true;
                                boardFit += 1;

                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurSwitch - adjustedPTKO >= 2 )
                                    boardFit += 1;
                            }
                        }

                        if( weHaveAlly && ourAlly != null && !targetsUs )
                        {
                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackerStatStageChanges: demoralize );

                            if( adjustedPTKO < theirPTKO_OurAlly )
