                            boardFit += 1;

                            if( theirAllyTargetsUs )
                                boardFit += 1;

                            if( theirAllyTargetsOurAlly )
                                boardFit += 1;

                            Dictionary<Stat, int> demoralize = new(){ { Stat.SpAttack, -1 } };

                            if( theirAllyTargetsUs )
                            {
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR_OurSwitch, theirAlly, ourSwitch, attackerStatStageChanges: demoralize );

                                if( adjustedPTKO < theirPTKO_Us )
                                {
                                    ourSwitchCanEnterSafely = true;
                                    
                                    boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                        boardFit += 1;
                                }
                            }

                            if( weHaveAlly && ourAlly != null && theirAllyTargetsOurAlly )
                            {
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, ourAlly, attackerStatStageChanges: demoralize );

                                if( adjustedPTKO < theirAllyPTKO_OurAlly )
                                {
                                    weCanCoverAlly = true;

                                    boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_OurAlly - adjustedPTKO >= 2 )
                                        boardFit += 1;
                                }

                                if( MovesBefore( theirAlly, ourAlly, ip.TurnOrder ) && adjustedPTKO <= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 2;
                                    offensiveAlignment++;
                                    weCanEnableAlly = true;
                                }
                                else if( adjustedPTKO <= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 3;
                                    offensiveAlignment++;
                                    weCanEnableAlly = true;
                                }
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.WeatherSetAbility || mainCapability == CapabilityObservation.CloudNine )
                {
                    var ourCandidateWeather = _ai.UnitSim.GetWeatherFrom_Ability( ourSwitch.Pokemon );

                    bool sandForce = them.Ability == AbilityID.SandForce && _ai.UnitSim.MoveIsSandforceBoosted( theirMove );
                    bool theirAttackBoostedByWeather =  currentWeather == WeatherConditionID.Sun && theirMove?.MoveType == PokemonType.Fire ||
                                                        currentWeather == WeatherConditionID.Rain && theirMove?.MoveType == PokemonType.Water ||
                                                        currentWeather == WeatherConditionID.Sand && sandForce ||
                                                        currentWeather == WeatherConditionID.Snow && theirMove?.MoveType == PokemonType.Ice;

                    if( theirPTKO_OurSwitch >= PotentialToKO.Risky && theirAttackBoostedByWeather )
                    {
                        float removeWeatherMod = 0f;
                        float addWeatherMod = 0f;

                        if( currentWeather == WeatherConditionID.Sun )
                        {
                            removeWeatherMod = 1.5f;
                            addWeatherMod = ourCandidateWeather == WeatherConditionID.Rain ? 0.5f : 1f;
                        }
                        else if( currentWeather == WeatherConditionID.Rain )
                        {
                            removeWeatherMod = 1.5f;
                            addWeatherMod = ourCandidateWeather == WeatherConditionID.Sun ? 0.5f : 1f;
                        }
                        else if( currentWeather == WeatherConditionID.Sand )
                        {
                            removeWeatherMod = sandForce ? 1.3f : 0f;
                        }
                        else if( currentWeather == WeatherConditionID.Snow )
                        {
                            removeWeatherMod = 1.5f;
                        }
                        
                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR_OurSwitch, them, ourSwitch, removeModifier: removeWeatherMod, addModifier: addWeatherMod );

                        if( adjustedPTKO < theirPTKO_OurSwitch )
                        {
                            ourSwitchCanEnterSafely = true;

                            boardFit += 1;

                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurSwitch - adjustedPTKO > 2 )
                                boardFit += 2;
                        }
                    }

                    if( weHaveAlly && ourAlly != null )
                    {
                        if( ourCandidateWeather == WeatherConditionID.Sun && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SunHelps ) )
                        {
                            boardFit += 2;
                            offensiveAlignment++;

                            weCanEnableAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                                boardFit += 2;

                            if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( ourAlly.Pokemon, ourCandidateWeather ) )
                            {
                                boardFit += 1;

                                if( ourAlly.Speed * 2 > them.Speed )
                                    boardFit += 1;

                                if( ourAlly.Speed * 2 > theirAlly?.Speed )
                                    boardFit += 1;

                                if( them.Speed > ourAlly.Speed && ourAlly.Speed * 2 > them.Speed && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }

                                if( theirAlly?.Speed > ourAlly.Speed && ourAlly.Speed * 2 > theirAlly?.Speed && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }

                        if( ourCandidateWeather == WeatherConditionID.Rain && ourAlly.RoleProfile.Traits.Contains( RoleTrait.RainHelps ) )
                        {
                            boardFit += 2;
                            offensiveAlignment++;

                            weCanEnableAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                                boardFit += 2;

                            if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( ourAlly.Pokemon, ourCandidateWeather ) )
                            {
                                boardFit += 1;

                                if( ourAlly.Speed * 2 > them.Speed )
                                    boardFit += 1;

                                if( ourAlly.Speed * 2 > theirAlly?.Speed )
                                    boardFit += 1;

                                if( them.Speed > ourAlly.Speed && ourAlly.Speed * 2 > them.Speed && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }

                                if( theirAlly?.Speed > ourAlly.Speed && ourAlly.Speed * 2 > theirAlly?.Speed && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }

                        if( ourCandidateWeather == WeatherConditionID.Sand && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SandHelps ) )
                        {
                            boardFit += 2;
                            offensiveAlignment++;

                            weCanEnableAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                                boardFit += 2;

                            if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( ourAlly.Pokemon, ourCandidateWeather ) )
                            {
                                boardFit += 1;

                                if( ourAlly.Speed * 2 > them.Speed )
                                    boardFit += 1;

                                if( ourAlly.Speed * 2 > theirAlly?.Speed )
                                    boardFit += 1;

                                if( them.Speed > ourAlly.Speed && ourAlly.Speed * 2 > them.Speed && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }

                                if( theirAlly?.Speed > ourAlly.Speed && ourAlly.Speed * 2 > theirAlly?.Speed && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }

                        if( ourCandidateWeather == WeatherConditionID.Snow && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SnowHelps ) )
                        {
                            boardFit += 2;
                            offensiveAlignment++;

                            weCanEnableAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                                boardFit += 2;

                            if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( ourAlly.Pokemon, ourCandidateWeather ) )
                            {
                                boardFit += 1;

                                if( ourAlly.Speed * 2 > them.Speed )
                                    boardFit += 1;

                                if( ourAlly.Speed * 2 > theirAlly?.Speed )
                                    boardFit += 1;

                                if( them.Speed > ourAlly.Speed && ourAlly.Speed * 2 > them.Speed && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }

                                if( theirAlly?.Speed > ourAlly.Speed && ourAlly.Speed * 2 > theirAlly?.Speed && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                {
                                    boardFit += 1;

                                    if( theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.TerrainSetAbility )
                {
                    var ourCandidateTerrain = _ai.UnitSim.GetTerrainFrom_Ability( ourSwitch.Pokemon );
                    bool theirAttackBoostedByTerrain =  currentTerrain == TerrainID.Blighted && ( theirMove?.MoveType == PokemonType.Dark || theirMove?.MoveType == PokemonType.Ghost ) ||
                                                        currentTerrain == TerrainID.Electric && theirMove?.MoveType == PokemonType.Electric ||
                                                        currentTerrain == TerrainID.Grassy && theirMove?.MoveType == PokemonType.Grass ||
                                                        currentTerrain == TerrainID.Misty && theirMove?.MoveType == PokemonType.Fairy ||
                                                        currentTerrain == TerrainID.Psychic && theirMove?.MoveType == PokemonType.Psychic;

                    bool grassyGlide = currentTerrain == TerrainID.Grassy && theirMove?.MoveSO.Name == "Grassy Glide";
                    bool expandingForce = currentTerrain == TerrainID.Psychic && theirMove?.MoveSO.Name == "Expanding Force";

                    if( grassyGlide || expandingForce )
                    {
                        boardFit += 1;
                        weCanRemoveTheirResources = true;
                        
                        if( theyTargetOurAlly || ( weHaveAlly && expandingForce ) )
                            weCanCoverAlly = true;
                    }

                    if( theirPTKO_OurSwitch >= PotentialToKO.Risky && theirAttackBoostedByTerrain )
                    {
                        float removeTerrainMod = 1.3f;
                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR_OurSwitch, them, ourSwitch, removeModifier: removeTerrainMod );

                        if( adjustedPTKO < theirAllyPTKO_OurSwitch )
                        {
                            ourSwitchCanEnterSafely = true;
                            defensiveAlignment++;

                            boardFit += 1;

                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurSwitch - adjustedPTKO > 2 )
                                boardFit += 2;
                        }
                    }

                    if( weHaveAlly && ourAlly != null )
                    {
                        bool allyBenefitsBlighted = ourCandidateTerrain == TerrainID.Blighted && ourAlly.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainHelps );
                        bool allyBenefitsElectric = ourCandidateTerrain == TerrainID.Electric && ourAlly.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainHelps );
                        bool allyBenefitsGrassy = ourCandidateTerrain == TerrainID.Grassy && ourAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainHelps );
                        bool allyBenefitsMisty = ourCandidateTerrain == TerrainID.Misty && ourAlly.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainHelps );
                        bool allyBenefitsPsychic = ourCandidateTerrain == TerrainID.Psychic && ourAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainHelps );

                        bool allyBenefitsTerrain = allyBenefitsBlighted || allyBenefitsElectric || allyBenefitsGrassy || allyBenefitsMisty || allyBenefitsPsychic;

                        if( allyBenefitsTerrain )
                        {
                            boardFit += 2;
                            offensiveAlignment++;

                            weCanEnableAlly = true;
                            weCanCreateBoardAdvantage = true;

                            if( allyBenefitsBlighted && ourAlly.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainAbuser ) )
                                boardFit += 2;

                            if( allyBenefitsElectric && ourAlly.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainAbuser ) )
                                boardFit += 2;

                            if( allyBenefitsGrassy && ourAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                            {
                                boardFit += 2;
                                if( TryExtractMoveFromPokemon( "Grassy Glide", ourSwitch, out var grassyGlideMove ) )
                                {
                                    var ggPTKO_Them = themVsOurSwitch.Target.CurrentPTKOs.ContainsKey( grassyGlideMove ) ? themVsOurSwitch.Target.CurrentPTKOs[grassyGlideMove] : PotentialToKO.Untouchable;
                                    var ggPTKO_TheirAlly = theyHaveAlly && theirAllyVsOurSwitch.Target.CurrentPTKOs.ContainsKey( grassyGlideMove ) ? theirAllyVsOurSwitch.Target.CurrentPTKOs[grassyGlideMove] : PotentialToKO.Untouchable;

                                    if( ggPTKO_Them >= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( ggPTKO_TheirAlly >= PotentialToKO.Risky )
                                        boardFit += 1;
                                }
                            }

                            if( allyBenefitsMisty && ourAlly.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainAbuser ) )
                                boardFit += 2;

                            if( allyBenefitsPsychic && ourAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                            {
                                boardFit += 2;
                                if( TryExtractMoveFromPokemon( "Expanding Force", ourSwitch, out var expandingForceMove ) )
                                {
                                    var efPTKO_Them = themVsOurSwitch.Target.CurrentPTKOs.ContainsKey( expandingForceMove ) ? themVsOurSwitch.Target.CurrentPTKOs[expandingForceMove] : PotentialToKO.Untouchable;
                                    var efPTKO_TheirAlly = theyHaveAlly && theirAllyVsOurSwitch.Target.CurrentPTKOs.ContainsKey( expandingForceMove ) ? theirAllyVsOurSwitch.Target.CurrentPTKOs[expandingForceMove] : PotentialToKO.Untouchable;

                                    if( efPTKO_Them >= PotentialToKO.Dangerous )
                                        boardFit += 1;

                                    if( efPTKO_TheirAlly >= PotentialToKO.Dangerous )
                                        boardFit += 1;
                                }
                            }
                        }
                    }
                }

                if( mainCapability == CapabilityObservation.TrapAbility )
                {
                    if( weHaveAlly )
                    {
                        boardFit += 1;
                        offensiveAlignment++;

                        if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                        {
                            boardFit += 2;
                            weCanEnableAlly = true;
                        }

                        if( them.BeginningHPR < 0.33f )
                            boardFit += 1;

                        if( theyHaveAlly && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                        {
                            boardFit += 2;
                            weCanEnableAlly = true;
                        }

                        if( theyHaveAlly && theirAlly?.BeginningHPR < 0.33f )
                            boardFit += 1;

                        if( asp.AllyCan.PerishSong )
                        {
                            boardFit += 3;
                            weCanEnableAlly = true;
                        }

                        if( _ai.CanUseFakeOut( ourSwitch, them ) )
                            boardFit += 1;

                        if( theyHaveAlly && _ai.CanUseFakeOut( ourSwitch, theirAlly ) )
                            boardFit += 1;

                        if( ourAlly.Pokemon.CheckHasActiveMove( "Protect" ) || ourAlly.Pokemon.CheckHasActiveMove( "Detect" ) )
                            boardFit += 1;

                        if( ourSwitch.Pokemon.CheckHasActiveMove( "Protect" ) || ourSwitch.Pokemon.CheckHasActiveMove( "Detect" ) )
                            boardFit += 1;

                        if( theirPTKO_OurSwitch <= PotentialToKO.TwoHKO )
                            boardFit += 1;

                        if( themVsOurSwitch.Target.BestCurrentPTKO >= PotentialToKO.Risky )
                            boardFit += 1;

                        if( theyHaveAlly && theirAllyPTKO_OurSwitch <= PotentialToKO.TwoHKO )
                            boardFit += 1;

                        if( theyHaveAlly && theirAllyVsOurSwitch.Target.BestCurrentPTKO >= PotentialToKO.Risky )
                            boardFit += 1;
                    }
                }

                if( mainCapability == CapabilityObservation.Hospitality && weHaveAlly )
                {
                    defensiveAlignment++;

                    if( ourAlly.BeginningHPR <= 0.33f )
                    {
                        boardFit += 3;
                        weCanCoverAlly = true;
                    }
                    else if( ourAlly.BeginningHPR <= 0.66f )
                    {
                        boardFit += 2;
                        weCanCoverAlly = true;
                    }
                    else if( ourAlly.BeginningHPR <= 1f )
                    {
                        boardFit += 1;

                        if( ourAlly.BeginningHPR < 1f )
                            weCanCoverAlly = true;
                    }

                    if( ourAlly.BeginningHPR < 1f && ourAlly.BeginningHPR >= 0.5f && ( ( ourAlly.Item != ItemBattleEffectID.None && ourAlly.RoleProfile.Traits.Contains( RoleTrait.FocusSash ) ) || ( ourAlly.Item != ItemBattleEffectID.FocusSash && ourAlly.Item != ItemBattleEffectID.None && ourAlly.RoleProfile.Traits.Contains( RoleTrait.FullHPSave ) ) ) )
                    {
                        boardFit += 3;
                        weCanEnableAlly = true;
                    }

                    if( theyTargetOurAlly && theirMove != null && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                    {
                        Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Attack : Stat.SpAttack;
                        
                        var newHPR = ourAlly.BeginningHPR + 0.25f;
                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackStat, defenseStat, newHPR: newHPR );

                        if( adjustedPTKO < theirPTKO_OurAlly )
                            boardFit += 1;

                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurAlly - adjustedPTKO >= 2 )
                            boardFit += 1;
                    }

                    if( MovesBefore( them, ourAlly, ip.TurnOrder ) && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                    {
                        boardFit += 2;

                        if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                        {
                            offensiveAlignment++;
                            weCanEnableAlly = true;
                            boardFit += 2;
                        }
                    }

                    if( theyHaveAlly && MovesBefore( theirAlly, ourAlly, ip.TurnOrder ) && theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                    {
                        boardFit += 2;

                        if( ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                        {
                            offensiveAlignment++;
                            weCanEnableAlly = true;
                            boardFit += 2;
                        }
                    }

                }

                //-------------
                //--Creations--
                //-------------
                if( weCanCoverAlly )
                    creations += 1;

                if( weCanEnableAlly )
                    creations += 1;

                if( weCanRemoveTheirResources )
                    creations += 1;

                if( weCanThreatenUtilityPressure )
                    creations += 1;

                if( weCanCreateBoardAdvantage )
                    creations += 1;

                if( ourSwitchCanEnterSafely )
                    creations += 1;

                //------------
                //--Unit Fit--
                //------------
                bool ourHPLow = us.BeginningHPR < 0.45f;

                if( ourHPLow && MovesBefore( them, us, ip.TurnOrder ) )
                    unitFit += 1;

                if( ourPTKO_Them <= PotentialToKO.TwoHKO && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                {
                    unitFit += 1;
                    offensiveAlignment++;
                }

                if( MovesBefore( them, us, ip.TurnOrder ) && ourPTKO_Them <= PotentialToKO.Risky && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                    unitFit += 1;

                if( ourHPLow && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive )
                {
                    unitFit += 1;
                    defensiveAlignment++;
                }

                if( ourHPLow && MovesBefore( them, us, ip.TurnOrder ) && us.Ability != AbilityID.Prankster && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                    unitFit += 1;

                bool switchHPLow = ourSwitch.BeginningHPR <= 0.5f;

                if( ourSwitch?.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                {
                    unitFit += 1;

                    if( mainCapability == CapabilityObservation.Intimidate || mainCapability == CapabilityObservation.Demoralize || mainCapability == CapabilityObservation.TrapAbility || mainCapability == CapabilityObservation.AbilityPriorityBlock )
                        unitFit += 1;
                }

                if( ourSwitch?.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                {
                    if( mainCapability == CapabilityObservation.WeatherSetAbility )
                    {
                        if( switchesWeather != currentWeather && _ai.UnitSim.PokemonHasMove_AbusesWeather( ourSwitch.Pokemon, switchesWeather ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }
                    }

                    if( mainCapability == CapabilityObservation.TerrainSetAbility )
                    {
                        if( switchesTerrain == TerrainID.Blighted && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.BlightedTerrainAbuser ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }

                        if( switchesTerrain == TerrainID.Electric && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.ElectricTerrainAbuser ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }

                        if( switchesTerrain == TerrainID.Grassy && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }

                        if( switchesTerrain == TerrainID.Misty && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.MistyTerrainAbuser ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }

                        if( switchesTerrain == TerrainID.Psychic && ourSwitch.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                        {
                            unitFit += 1;
                            offensiveAlignment++;
                        }
                    }
                }

                //--ptko exchanges
                if( theirPTKO_Us >= PotentialToKO.Dangerous )
                {
                    unitFit += 1;
                    defensiveAlignment++;

                    if( ourPTKO_Them <= PotentialToKO.Risky || MovesBefore( them, us, ip.TurnOrder ) )
                        unitFit += 1;
                }

                if( theirPTKO_OurSwitch >= PotentialToKO.Dangerous )
                {
                    unitFit -= 1;

                    if( switchHPLow )
                        unitFit -= 1;

                    if( mainCapability == CapabilityObservation.WeatherSetAbility )
                    {
                        if( theirSP.DependsOnCurrentWeather || theirAllySP.DependsOnCurrentWeather )
                        {
                            unitFit += 1;
                        }
                    }
                }

                //--speed comparisons
                if( them.Speed > us.Speed && ourSwitch.Speed > them.Speed )
                    unitFit += 1;

                if( mainCapability == CapabilityObservation.WeatherSetAbility )
                {
                    if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( them.Pokemon, currentWeather ) )
                    {
                        offensiveAlignment++;

                        if( them.Pokemon.Speed / 2 < ourSwitch.Speed || them.Pokemon.Speed / 2 < ourAlly?.Speed )
                            unitFit += 1;
                    }

                    if( theirAlly != null && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( theirAlly.Pokemon, currentWeather ) )
                    {
                        offensiveAlignment++;

                        if( theirAlly.Pokemon.Speed / 2 < ourSwitch.Speed || theirAlly.Pokemon.Speed / 2 < ourAlly?.Speed )
                            unitFit += 1;
                    } 
                }

                //------------
                //--Plan Fit--
                //------------
                bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                bool ourallyIsWincon = ourAlly != null && ourAlly.Pokemon == gp.OurPrimaryWinCon;
                bool ourAllyIsBlocker = ourAlly != null && gp.OurBlockers.Contains( ourAlly.Pokemon );
                bool ourAllyIsEnabler = ourAlly != null && gp.OurEnablers.Contains( ourAlly.Pokemon );

                bool ourSwitchIsWincon = ourSwitch != null && ourSwitch.Pokemon == gp.OurPrimaryWinCon;
                bool ourSwitchIsBlocker = ourSwitch != null && gp.OurBlockers.Contains( ourSwitch.Pokemon );
                bool ourSwitchIsEnabler = ourSwitch != null && gp.OurEnablers.Contains( ourSwitch.Pokemon );

                // bool theyAreWincon = them.Pokemon == gp.TheirPrimaryWinCon; //--These were written in the data gathering block of the function
                // bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon ); //--These were written in the data gathering block of the function
                bool theyAreEnabler = gp.TheirEnablers.Contains( them.Pokemon );

                bool theirAllyIsWincon = theirAlly != null && theirAlly.Pokemon == gp.TheirPrimaryWinCon;
                bool theirAllyIsBlocker = theirAlly != null && gp.TheirBlockers.Contains( theirAlly.Pokemon );
                bool theirAllyIsEnabler = theirAlly != null && gp.TheirEnablers.Contains( theirAlly.Pokemon );

                if( weAreWincon && ( theyAreBlocker || theirAllyIsBlocker ) )
                {
                    planFit += 1;
                    defensiveAlignment++;
                }

                if( ( ourSwitchIsWincon && ourAllyIsEnabler ) || ( ourSwitchIsEnabler && ourallyIsWincon ) )
                {
                    planFit += 1;
                    offensiveAlignment++;
                }

                if( ( theyAreWincon || theirAllyIsWincon ) && ourSwitchIsBlocker )
                {
                    planFit += 1;
                    defensiveAlignment++;
                }

                if( ourSwitchIsWincon && ( theyAreBlocker || theirAllyIsBlocker ) )
                {
                    planFit -= 1;

                    if( theyAreBlocker && theirAllyIsBlocker )
                        planFit -= 1;
                }

                if( CheckIfPokemonHasSpecificCapability( us.Pokemon, CapabilityObservation.WeatherSetAbility, capabilitySets ) )
                {
                    var ourTeamComp = _ai.Blackboard.OurTeamComposition;
                    if( currentWeather == WeatherConditionID.Sun && ourTeamComp.Strategies.Contains( TeamStrategy.Sun ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                    {
                        planFit += 1;
                        offensiveAlignment++;
                    }

                    if( currentWeather == WeatherConditionID.Rain && ourTeamComp.Strategies.Contains( TeamStrategy.Rain ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                    {
                        planFit += 1;
                        offensiveAlignment++;
                    }

                    if( currentWeather == WeatherConditionID.Sand && ourTeamComp.Strategies.Contains( TeamStrategy.Sand ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                    {
                        planFit += 1;
                        offensiveAlignment++;
                    }

                    if( currentWeather == WeatherConditionID.Snow && ourTeamComp.Strategies.Contains( TeamStrategy.Snow ) && ourTeamComp.Strategies.Contains( TeamStrategy.WeatherAbuse ) )
                    {
                        planFit += 1;
                        offensiveAlignment++;
                    }
                }

                //-------------
                //--Cost/Risk--
                //-------------

                //--Switch Tax
                costRisk += 1;

                if( theirPTKO_OurSwitch >= PotentialToKO.Dangerous )
                {
                    costRisk += 1;
                }

                if( theirAllyPTKO_OurSwitch >= PotentialToKO.Dangerous )
                {
                    costRisk += 1;
                }

                if( theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                    costRisk += 1;

                if( theirAllyTargetsOurAlly && theirAllyPTKO_OurAlly >= PotentialToKO.Dangerous )
                    costRisk += 1;

                if( theyTargetOurAlly && theirAllyTargetsOurAlly )
                {
                    if( theirPTKO_OurAlly >= PotentialToKO.Risky && theirAllyPTKO_OurAlly >= PotentialToKO.Risky )
                        costRisk += 1;
                }

                if( theirAllyTargetsUs )
                {
                    costRisk += 1;

                    if( targetsUs )
                        costRisk += 1;
                }

                if( ip.AttackerMovesFirst && ourPTKO_Them >= PotentialToKO.Dangerous )
                    costRisk += 1;

                if( theirAction != ActionType.Attack && theirAction != ActionType.Protect )
                {
                    if( us.RoleProfile.Traits.Contains( RoleTrait.PriorityBlockAbility ) && them.Ability == AbilityID.Prankster )
                        costRisk += 1;

                    if( ip.WeCan.FakeOut )
                        costRisk += 1;
                }

                if( theirAllyHasIntent && theirAllyTargetsUs && theirAllyAction != ActionType.Attack && theirAllyAction != ActionType.Protect )
                {
                    if( us.RoleProfile.Traits.Contains( RoleTrait.PriorityBlockAbility ) && theirAlly.Ability == AbilityID.Prankster )
                        costRisk += 1;

                    if( ip.WeCan.FakeOut )
                        costRisk += 1;
                }
                
                int finalScore = creations + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    DefensiveAlignment = defensiveAlignment,
                    OffensiveAlignment = offensiveAlignment,

                    CreationScore = creations,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                if( defensiveAlignment > offensiveAlignment )
                    candidate.ChangeActionType( ActionType.DefensiveSwitch );
                else if( offensiveAlignment > defensiveAlignment )
                    candidate.ChangeActionType( ActionType.OffensiveSwitch );
                else
                    candidate.ChangeActionType( ActionType.DefensiveSwitch );

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSetupOpportunities( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> capabilityCandidates = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon );

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon );

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();

            if( capabilitySets.TryGetValue( unit.Pokemon, out var monCapabilities ) )
            {
                foreach( var capability in monCapabilities )
                {
                    if( GetCapabilityActionType( capability ) != ActionType.Setup )
                        continue;

                    foreach( var opp in theirActive )
                    {
                        var candidate = GetSetupCandidate( capability, unit, opp, CoordinationActionType.Opportunity );
                        candidates.Add( candidate );
                    }
                }
            }

            if( candidates?.Count <= 0 )
                continue;

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int creations = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );
                var ourSwitch = candidate.SwitchCandidate != null ? _ai.GetPokemonAs_IBattleAIUnit( candidate.SwitchCandidate ) : null;
                bool weHaveSwitch = ourSwitch != null;

                var ip = GetInteractionProfile( us, them, candidate, null );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var ourSwitchSP = ourSwitch != null ? _ai.Projection.GetStrategicProfile( ourSwitch ) : default;
                var theirSP = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;
                bool theyAreWincon = gp.TheirPrimaryWinCon == them.Pokemon;
                bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                bool theyAreEneabler = gp.TheirEnablers.Contains( them.Pokemon );

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                var ourPTKO_Them = ip.AttackerPTKO;
                var theirPTKO_Us = ip.TargetPTKO;
                var attackerMovesFirst = ip.AttackerMovesFirst;

                var theirAction = ip.TheirAction;
                var theirActionResult = ip.TheirActionResult;
                var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                var theirEDR = theirMTR != null ? theirMTR.EDR : default;

                var theirAllyAction = ip.TheirAllyAction;
                var theirAllyActionResult = ip.TheirAllyActionResult;
                bool theirAllyHasIntent = ip.TheirAllyHasIntent;
                var theirAllyMTR = theirAllyHasIntent && theirAllyActionResult is MoveThreatResult taresult ? taresult : null;
                var theirAllyEDR = theirAllyMTR != null ? theirAllyMTR.EDR : default;

                var ourAlly = ip.AttackerAlly;
                var theirAlly = ip.TargetAlly;

                bool weHaveAlly = ourAlly != null;
                bool theyHaveAlly = theirAlly != null;

                var asp = weHaveAlly ? GetAllySynergyProfile( us, ourAlly, them, candidate ) : default;

                var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                bool theyAttack = theirAction == ActionType.Attack;
                bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                bool theySetup = theirAction == ActionType.Setup;
                bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                bool theyProtect = theirAction == ActionType.Protect;

                bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                var theirMove = theirActionResult.Move;

                bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                bool theirAllyUsesMove = theyHaveAlly && theirAllyMove != null;
                bool theirAllyTargetsUs = theyHaveAlly && theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                bool theirAllyTargetsOurAlly = theyHaveAlly && theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                var ourPTKO_TheirAlly = theyHaveAlly ? ip.UsVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                var theirAllyVsOurSwitch = theyHaveAlly && weHaveSwitch ? _ai.Projection.MakeUnitComparison( theirAlly, ourSwitch ) : default;
                var theirAllyEDR_OurSwitch = theyHaveAlly && weHaveSwitch && theirAllyMove != null ? GetEDROnSwitchCandidate( theirAlly, ourSwitch, theirAllyMove ) : default;
                var theirAllyPTKO_OurSwitch = theyHaveAlly && weHaveSwitch && theirAllyMove != null ? _ai.Projection.GetPTKO_FromDamageEstimate( theirAllyEDR_OurSwitch, ourSwitch ) : PotentialToKO.Untouchable;
                
                var themVsOurSwitch = ourSwitch != null ? _ai.Projection.MakeUnitComparison( them, ourSwitch ) : default;
                var theirEDR_OurSwitch = ourSwitch != null && theirMove != null ? GetEDROnSwitchCandidate( them, ourSwitch, theirMove ) : default;
                var theirPTKO_OurSwitch = ourSwitch != null && theirMove != null ? _ai.Projection.GetPTKO_FromDamageEstimate( theirEDR_OurSwitch, ourSwitch ) : PotentialToKO.Untouchable;

                var ourAllyMove_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : null;
                var ourAllyMove_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() : null;

                bool theyHavePrankster = them.Ability == AbilityID.Prankster;
                bool theyAreUsingPrankster = theyUseAMove && theirMove?.MoveSO.MoveCategory == MoveCategory.Status;
                bool theirPranksterIsOffensive = theyAreUsingPrankster && theirAction == ActionType.OffensiveStatus;
                bool theirMoveHasPriority = theyUseAMove && theirMove?.Priority > MovePriority.Zero;

                bool theirAllyHasPrankster = theyHaveAlly && theirAlly?.Ability == AbilityID.Prankster;
                bool theirAllyIsUsingPrankster = theirAllyUsesMove && theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Status;
                bool theirAllyPranksterIsOffensive = theirAllyIsUsingPrankster && theirAllyAction == ActionType.OffensiveStatus;
                bool theirAllyMoveHasPriority = theyHaveAlly && theirAllyUsesMove && theirAllyMove?.Priority > MovePriority.Zero;
                
                SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                var theirSwitch = theySwitch ? scr.Candidate : null;
                bool theyHaveSwitch = theirSwitch != null;
                var usVsSwitch = theyHaveSwitch && theirSwitch != null ? _ai.Projection.MakeUnitComparison( us, theirSwitch ) : default;

                List<IBattleAIUnit> targetsTargets = ip.TheirActionResult.Targets != null && ip.TheirActionResult.Targets.Count > 0 ? ip.TheirActionResult.Targets : null;
                bool targetsUs = targetsTargets != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );

                //--Creation Flags
                bool weCanReduceTheirThreat = false;
                bool weCanEnableOurAlly = false;
                bool weCanCoverOurAlly = false;
                bool weCanThreatenBigDamageAcrossTheBoard = false;
                bool weCanThreatenUtilityPressure = false;
                bool weCanRemoveTheirResources = false;
                bool weCanCreateBoardAdvantage = false;
                bool candidateHasBatonPass = us.Pokemon.CheckHasActiveMove( "Baton Pass" );

                //-------------
                //--Board Fit--
                //-------------
                if( mainCapability == CapabilityObservation.Substitute )
                {
                    if( theirAction == ActionType.OffensiveStatus || ( theyHaveAlly && theirAllyAction == ActionType.OffensiveStatus ) )
                            weCanRemoveTheirResources = true;

                    if( theyTargetUs )
                    {
                        if( ( theirAction == ActionType.Attack || theirAction == ActionType.OffensiveStatus ) && MovesBefore( us, them, ip.TurnOrder ) )
                        {
                            boardFit += 1;

                            if( theirAction == ActionType.Attack && theirPTKO_Us <= PotentialToKO.Risky )
                            {
                                boardFit += 1;

                                if( theirPTKO_Us <= PotentialToKO.Sturdy )
                                {
                                    boardFit += 1;
                                    weCanCreateBoardAdvantage = true;
                                    weCanReduceTheirThreat = true;
                                }
                            }
                        }
                        else if( theirPTKO_Us <= PotentialToKO.Sturdy )
                        {
                            boardFit += 1;
                            weCanCreateBoardAdvantage = true;
                            weCanReduceTheirThreat = true;
                        }
                        else
                            boardFit -= 2;
                    }
                    else
                        boardFit += 2;

                    if( theySwitch )
                        boardFit += 2;

                    if( theyHaveAlly && theirAllyHasIntent && theirAllyTargetsUs )
                    {
                        if( ( theirAllyAction == ActionType.Attack || theirAllyAction == ActionType.OffensiveStatus ) && MovesBefore( us, theirAlly, ip.TurnOrder ) )
                        {
                            boardFit += 1;

                            if( theirAllyPTKO_Us <= PotentialToKO.Risky )
                            {
                                boardFit += 1;

                                if( theirAllyPTKO_Us <= PotentialToKO.Sturdy )
                                {
                                    boardFit += 1;
                                    weCanCreateBoardAdvantage = true;
                                    weCanReduceTheirThreat = true;
                                }
                            }
                        }
                        else if( theirAllyPTKO_Us <= PotentialToKO.Sturdy )
                        {
                            boardFit += 1;
                            weCanCreateBoardAdvantage = true;
                            weCanReduceTheirThreat = true;
                        }
                        else
                            boardFit -= 2;
                    }
                    else
                        boardFit += 2;

                    if( theyHaveAlly && theirAllySwitches )
                        boardFit += 2;

                    if( us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility && weHaveAlly && ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                    {
                        boardFit += 1;
                        weCanEnableOurAlly = true;
                    }
                }

                int atkBoosts = 0;
                int spAtkBoosts = 0;
                int defBoosts = 0;
                int spDefBoosts = 0;
                int speedBoosts = 0;
                int totalBoosts = 0;

                if( mainCapability == CapabilityObservation.StatBoost )
                {
                    if( theyTargetUs )
                    {
                        if( theirAction == ActionType.Attack && theirPTKO_Us <= PotentialToKO.TwoHKO )
                            boardFit += 1;
                        else
                            boardFit -= 1;

                        bool fasterTaunt = theirMove?.MoveSO.Name == "Taunt" && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                        if( theirAction == ActionType.OffensiveStatus && ( fasterTaunt || theirMove?.MoveSO.Name == "Encore" ) )
                            boardFit -= 2;
                    }

                    if( theirAllyTargetsUs )
                    {
                        if( theirAllyAction == ActionType.Attack && theirAllyPTKO_Us <= PotentialToKO.TwoHKO )
                            boardFit += 1;
                        else
                            boardFit -= 1;

                        bool fasterTaunt = theirAllyMove?.MoveSO.Name == "Taunt" && ( theirAlly?.Ability == AbilityID.Prankster || theirAlly?.Speed > us.Speed );
                        if( theirAction == ActionType.OffensiveStatus && ( fasterTaunt || theirAllyMove?.MoveSO.Name == "Encore" ) )
                            boardFit -= 2;
                    }

                    var setupMove = candidate.MoveCandidate;
                    if( setupMove != null && setupMove.MoveEffects.StatChangeList?.Count > 0 )
                    {
                        foreach( var sc in setupMove.MoveEffects.StatChangeList )
                        {
                            if( sc.Stat == Stat.Attack && sc.Change > 0 )
                                atkBoosts += sc.Change;

                            if( sc.Stat == Stat.SpAttack && sc.Change > 0 )
                                spAtkBoosts += sc.Change;

                            if( sc.Stat == Stat.Defense && sc.Change > 0 )
                                defBoosts += sc.Change;

                            if( sc.Stat == Stat.SpDefense && sc.Change > 0 )
                                spDefBoosts += sc.Change;

                            if( sc.Stat == Stat.Speed && sc.Change > 0 )
                                speedBoosts += sc.Change;
                        }

                        totalBoosts = atkBoosts + spAtkBoosts + defBoosts + spDefBoosts + speedBoosts;
                        int newSpeed = Mathf.FloorToInt( us.Speed * _stageModifier[speedBoosts] );

                        if( newSpeed > them.Speed )
                        {
                            boardFit += 1;

                            if( them.Speed > us.Speed )
                            {
                                boardFit += 1;
                                weCanCreateBoardAdvantage = true;
                            }
                        }

                        if( newSpeed > theirAlly?.Speed )
                        {
                            boardFit += 1;

                            if( theirAlly?.Speed > us.Speed )
                            {
                                boardFit += 1;
                                weCanCreateBoardAdvantage = true;
                            }
                        }

                        if( theyTargetUs && theirMove?.MoveSO.MoveCategory != MoveCategory.Status )
                        {
                            Stat attackStat = theirMove?.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;

                            if( ( attackStat == Stat.Attack && defBoosts > 0 ) || ( attackStat == Stat.SpAttack && spDefBoosts > 0 ) )
                            {
                                Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;
                                Dictionary<Stat, int> statChanges = new();

                                if( defenseStat == Stat.Defense )
                                    statChanges.Add( Stat.Defense, defBoosts );
                                else if( defenseStat == Stat.SpDefense )
                                    statChanges.Add( Stat.SpDefense, spDefBoosts );
                                
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, targetStatStageChanges: statChanges );

                                if( adjustedPTKO < theirPTKO_Us )
                                    boardFit += 1;

                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                    boardFit += 1;
                            }
                        }

                        if( theirAllyTargetsUs && theirAlly != null && theirAllyMove?.MoveSO.MoveCategory != MoveCategory.Status )
                        {
                            Stat attackStat = theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;

                            if( ( attackStat == Stat.Attack && defBoosts > 0 ) || ( attackStat == Stat.SpAttack && spDefBoosts > 0 ) )
                            {
                                Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;
                                Dictionary<Stat, int> statChanges = new();

                                if( defenseStat == Stat.Defense )
                                    statChanges.Add( Stat.Defense, defBoosts );
                                else if( defenseStat == Stat.SpDefense )
                                    statChanges.Add( Stat.SpDefense, spDefBoosts );
                                
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, targetStatStageChanges: statChanges );

                                if( adjustedPTKO < theirPTKO_Us )
                                    boardFit += 1;

                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                    boardFit += 1;
                            }
                        }
                    }
                }

                if( weHaveAlly )
                {
                    if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) )
                    {
                        boardFit += 2;
                        weCanCreateBoardAdvantage = true;
                        weCanThreatenUtilityPressure = true;
                    }

                    if( ( theyTargetUs && _ai.CanUseFakeOut( ourAlly, them ) ) || ( theirAlly != null && theirAllyTargetsUs && _ai.CanUseFakeOut( ourAlly, theirAlly ) ) )
                    {
                        boardFit += 2;
                        weCanCreateBoardAdvantage = true;
                        weCanThreatenUtilityPressure = true;
                    }
                }

                //-------------
                //--Creations--
                //-------------
                if( weCanReduceTheirThreat )
                    creations += 1;
                    
                if( weCanEnableOurAlly )
                    creations += 1;
                    
                if( weCanCoverOurAlly )
                    creations += 1;
                    
                if( weCanThreatenBigDamageAcrossTheBoard )
                    creations += 1;
                    
                if( weCanThreatenUtilityPressure )
                    creations += 1;
                    
                if( weCanRemoveTheirResources )
                    creations += 1;
                    
                if( weCanCreateBoardAdvantage )
                    creations += 1;
                    
                if( candidateHasBatonPass )
                    creations += 1;
                    

                //------------
                //--Unit Fit--
                //------------
                if( mainCapability == CapabilityObservation.Substitute )
                {
                    if( us.BeginningHPR >= 0.7f )
                        unitFit += 1;

                    if( us.RoleProfile.Traits.Contains( RoleTrait.StatBooster ) )
                        unitFit += 1;

                    if( us.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) || us.RoleProfile.Biases.Contains( RoleBias.Disruptive ) )
                    {
                        unitFit += 1;
                        weCanCoverOurAlly = true;
                    }

                    if( theyTargetUs && theirPTKO_Us <= PotentialToKO.Sturdy && ourPTKO_Them >= PotentialToKO.Risky )
                        unitFit += 1;

                    if( theirAllyTargetsUs && theirAllyPTKO_Us <= PotentialToKO.Sturdy && ourPTKO_TheirAlly >= PotentialToKO.Risky )
                        unitFit += 1;

                    if( ( !theyTargetUs && theirAllyTargetsUs ) || ( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) ) )
                        unitFit += 1;
                }

                if( mainCapability == CapabilityObservation.StatBoost )
                {
                    var setupMove = candidate.MoveCandidate;

                    if( us.RoleProfile.Biases.Contains( RoleBias.Physical ) && atkBoosts > 0 )
                    {
                        unitFit += 1;

                        if( us.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack ) )
                        {
                            unitFit += 1;
                            weCanThreatenBigDamageAcrossTheBoard = true;
                        }
                    }

                    if( us.RoleProfile.Biases.Contains( RoleBias.Special ) && spAtkBoosts > 0 )
                    {
                        unitFit += 1;

                        if( us.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack ) )
                        {
                            unitFit += 1;
                            weCanThreatenBigDamageAcrossTheBoard = true;
                        }
                    }

                    if( us.RoleProfile.Biases.Contains( RoleBias.PhysicallyBulky ) && defBoosts > 0 )
                        unitFit += 1;

                    if( us.RoleProfile.Biases.Contains( RoleBias.SpeciallyBulky ) && spDefBoosts > 0 )
                        unitFit += 1;

                    if( defBoosts > 0 && us.Pokemon.CheckHasActiveMove( "Body Press" ) )
                        unitFit += 1;

                    if( us.Pokemon.CheckHasActiveMove( "Stored Power" ) || us.Pokemon.CheckHasActiveMove( "Baton Pass" ) )
                    {
                        if( totalBoosts > 3 )
                            unitFit += 3;
                        else if( totalBoosts > 1 )
                            unitFit += 2;
                        else if( totalBoosts > 0 )
                            unitFit += 1;

                        if( us.Pokemon.CheckHasActiveMove( "Baton Pass" ) )
                            weCanEnableOurAlly = true;

                        if( us.Pokemon.CheckHasActiveMove( "Stored Power" ) )
                        {
                            weCanCreateBoardAdvantage = true;
                            weCanThreatenBigDamageAcrossTheBoard = true;
                        }
                    }
                }

                //------------
                //--Plan Fit--
                //------------
                bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                bool ourAllyIsWincon = ourAlly != null && ourAlly.Pokemon == gp.OurPrimaryWinCon;
                bool ourAllyIsBlocker = ourAlly != null && gp.OurBlockers.Contains( ourAlly.Pokemon );
                bool ourAllyIsEnabler = ourAlly != null && gp.OurEnablers.Contains( ourAlly.Pokemon );

                bool theyHaveWincon = them.Pokemon == gp.TheirPrimaryWinCon || ( theirAlly != null && theirAlly.Pokemon == gp.TheirPrimaryWinCon );
                bool theyHaveBlocker = gp.TheirBlockers.Contains( them.Pokemon ) || ( theirAlly != null && gp.TheirBlockers.Contains( theirAlly.Pokemon ) );
                bool theyHaveEnabler = gp.TheirEnablers.Contains( them.Pokemon ) || ( theirAlly != null && gp.TheirEnablers.Contains( theirAlly.Pokemon ) );

                if( mainCapability == CapabilityObservation.Substitute )
                {
                    if( weAreWincon || weAreBlocker || weAreEnabler )
                        planFit += 1;

                    if( weAreWincon && ( theyHaveWincon || theyHaveBlocker || theyHaveEnabler ) )
                        planFit += 1;

                    if( weAreBlocker && theyHaveWincon )
                        planFit += 1;

                    if( ( weAreWincon && ourAllyIsEnabler ) || ( weAreEnabler && ourAllyIsWincon ) )
                        planFit += 1;
                }

                if( weAreWincon && ( atkBoosts > 0 || spAtkBoosts > 0 ) )
                {
                    planFit += 1;

                    if( theyHaveWincon )
                        planFit += 1;

                    if( ourAllyIsEnabler )
                        planFit += 1;
                }

                if( weAreWincon && theyHaveBlocker && ( defBoosts > 0 || spDefBoosts > 0 ) )
                {
                    planFit += 1;

                    if( ourAllyIsBlocker )
                        planFit += 1;

                    if( ourAllyIsEnabler )
                        planFit += 1;
                }

                if( weAreBlocker && theyHaveWincon && ( atkBoosts > 0 || defBoosts > 0 || spAtkBoosts > 0 || spDefBoosts > 0 ) )
                    planFit += 1;

                if( weAreEnabler && speedBoosts > 0 )
                    planFit += 1;

                //-------------
                //--Cost/Risk--
                //-------------
                if( mainCapability == CapabilityObservation.Substitute )
                {
                    if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                        costRisk += 1;

                    if( theyTargetUs && theirAllyTargetsUs )
                    {
                        if( MovesBefore( them, theirAlly, ip.TurnOrder ) && theirPTKO_Us >= PotentialToKO.Safe && theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                            costRisk += 1;

                        if( MovesBefore( theirAlly, them, ip.TurnOrder) && theirAllyPTKO_Us >= PotentialToKO.Safe && theirPTKO_Us >= PotentialToKO.Dangerous )
                            costRisk += 1;
                    }

                    if( us.BeginningHPR <= 0.75f )
                    {
                        costRisk += 1;

                        if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                            costRisk += 1;
                    }

                    if( them.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                        costRisk += 1;

                    if( theirAlly != null && ( theirAlly.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) ) )
                        costRisk += 1;

                    if( ourPTKO_Them >= PotentialToKO.Dangerous && ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Safe ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Safe ) )
                        costRisk += 1;
                }

                if( mainCapability == CapabilityObservation.StatBoost )
                {
                    if( ourPTKO_Them >= PotentialToKO.Dangerous && ( theirPTKO_Us <= PotentialToKO.TwoHKO || us.Speed > them.Speed ) )
                        costRisk += 1;

                    if( ourPTKO_TheirAlly >= PotentialToKO.Dangerous && ( theirAllyPTKO_Us <= PotentialToKO.TwoHKO || us.Speed > theirAlly?.Speed ) )
                        costRisk += 1;

                    if( ( theyTargetUs && theirPTKO_Us >= PotentialToKO.Risky ) || ( theirAllyTargetsUs && theirAllyPTKO_Us >= PotentialToKO.Risky ) )
                    {
                        if( ip.WeCan.Protect )
                            costRisk += 1;

                        if( ourBench.Count > 0 )
                            costRisk += 1;
                    }

                    if( totalBoosts > 0 && ( ( us.Speed < them.Speed && theirPTKO_Us > PotentialToKO.TwoHKO ) || ( us.Speed < theirAlly?.Speed && theirAllyPTKO_Us > PotentialToKO.TwoHKO ) ) )
                        costRisk += 1;

                    if( them.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || them.RoleProfile.Traits.Contains( RoleTrait.Haze ) )
                        costRisk += 2;

                    if( theirAlly != null && ( theirAlly.RoleProfile.Traits.Contains( RoleTrait.Phazes ) || theirAlly.RoleProfile.Traits.Contains( RoleTrait.Haze ) ) )
                        costRisk += 2;

                    bool theyFasterTaunt = them.RoleProfile.Traits.Contains( RoleTrait.Taunt ) && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                    bool theirAllyFasterTaunt = theirAlly != null && theirAlly.RoleProfile.Traits.Contains( RoleTrait.Taunt ) && ( theirAlly.Ability == AbilityID.Prankster || theirAlly.Speed > us.Speed );
                    bool theyFasterEncore = them.RoleProfile.Traits.Contains( RoleTrait.Encore ) && ( them.Ability == AbilityID.Prankster || them.Speed > us.Speed );
                    bool theirAllyFasterEncore = theirAlly != null && theirAlly.RoleProfile.Traits.Contains( RoleTrait.Encore ) && ( theirAlly.Ability == AbilityID.Prankster || theirAlly.Speed > us.Speed );

                    if( theyFasterTaunt || theirAllyFasterTaunt )
                        costRisk += 1;

                    if( theyFasterEncore || theirAllyFasterEncore )
                        costRisk += 2;
                }

                int finalScore = creations + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    CreationScore = creations,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                capabilityCandidates.Add( candidate, scores );
            }
        }

        return capabilityCandidates;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetOffensiveStatusOpportunities( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> capabilityCandidates = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon );

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon );

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();

            if( capabilitySets.TryGetValue( unit.Pokemon, out var monCapabilities ) )
            {
                foreach( var capability in monCapabilities )
                {
                    if( GetCapabilityActionType( capability ) != ActionType.OffensiveStatus )
                        continue;

                    foreach( var opp in theirActive )
                    {
                        var candidate = GetOffensiveStatusCandidate( capability, unit, opp, CoordinationActionType.Opportunity );
                        candidates.Add( candidate );
                    }
                }
            }

            if( candidates?.Count <= 0 )
                continue;

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int creations = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                bool statusEffect = false; //--eventually need to separate into severe status and volatile status for confusion and affection and such --08/18/26
                bool disruption = false;
                bool entryHazard = false;
                bool statDebuff = false;
                bool phaze = false;

                bool reflectable = candidate.MoveCandidate != null && candidate.MoveCandidate.MoveSO.Flags != null && candidate.MoveCandidate.MoveSO.Flags.Count > 0 && candidate.MoveCandidate.MoveSO.Flags.Contains( MoveFlags.Reflectable );
                bool theyReflect = candidate.Target?.AbilityID == AbilityID.MagicBounce;
                bool theyBlock = candidate.Target?.AbilityID == AbilityID.MagicGuard || candidate.Target?.AbilityID == AbilityID.GoodAsGold;

                if( theyBlock )
                    continue;

                if( reflectable && theyReflect )
                    continue;

                if( candidate.Actor.VolatileStatuses.ContainsKey( VolatileConditionID.Taunt ) )
                    continue;

                if( candidate.Actor?.AbilityID == AbilityID.Prankster && candidate.Target != null && candidate.Target.CheckTypes( PokemonType.Dark ) )
                    continue;

                switch( mainCapability )
                {
                    //--Status Effect
                    case CapabilityObservation.Wisp:
                    case CapabilityObservation.Hoarfrost:
                    case CapabilityObservation.Paralysis:
                    case CapabilityObservation.Sleep:
                    case CapabilityObservation.Toxic:
                        statusEffect = true;
                    break;

                    //--Disruption
                    case CapabilityObservation.Taunt:
                    case CapabilityObservation.Encore:
                    case CapabilityObservation.Disable:
                    case CapabilityObservation.Torment:
                    case CapabilityObservation.Imprison:
                    case CapabilityObservation.HealBlock:
                    case CapabilityObservation.PerishSong:
                        disruption = true;
                    break;

                    //--Entry Hazard
                    case CapabilityObservation.HazardSetting:
                        entryHazard = true;
                    break;

                    //--Stat Debuff
                    case CapabilityObservation.StatDebuff:
                        statDebuff = true;
                    break;

                    case CapabilityObservation.Phazing:
                        phaze = true;
                    break;
                }

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );
                var ourSwitch = candidate.SwitchCandidate != null ? _ai.GetPokemonAs_IBattleAIUnit( candidate.SwitchCandidate ) : null;

                var ip = GetInteractionProfile( us, them, candidate, null );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var ourSwitchSP = ourSwitch != null ? _ai.Projection.GetStrategicProfile( ourSwitch ) : default;
                var theirSP = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;
                bool theyAreWincon = gp.TheirPrimaryWinCon == them.Pokemon;
                bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                bool theyAreEneabler = gp.TheirEnablers.Contains( them.Pokemon );

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                var ourPTKO_Them = ip.AttackerPTKO;
