                            if( remove >= 0 )
                                ourBench.RemoveAt( remove );

                            attackerAlly = ourBench?.Count > 0 ? _ai.GetSwitch_CurrentPressure( theirActive, bench: ourBench ) : null;
                            attackerAllyReplaced = true;
