                        {
                            opponentAlly = theirBench?.Count > 0 ? _ai.GetSwitch_CurrentPressure( ourActive, bench: theirBench ) : null;
                            opponentAllyReplaced = true;

                            int remove = -1;
                            for( int i = 0; i < theirBench.Count; i++ )
