        if( haveAttacker && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( attacker.Pokemon, currentWeather ) && !_ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( attacker.Pokemon, nextWeather ) )
