        if( haveAttackerAlly && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( attackerAlly.Pokemon, currentWeather ) && !_ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( attackerAlly.Pokemon, nextWeather ) )
