        if( haveAttacker && _ai.UnitSim.PokemonIsHarmedBy_Weather( attacker, nextWeather ) || haveAttackerAlly && _ai.UnitSim.PokemonIsHarmedBy_Weather( attackerAlly, nextWeather ) )
            ourPBF.HurtByWeather = true;

