        if( haveOpponent && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( opponent.Pokemon, currentWeather ) && !_ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( opponent.Pokemon, nextWeather ) )
