        if( haveOpponent && _ai.UnitSim.PokemonBenefits_Weather( opponent, nextWeather ) || haveOpponentAlly && _ai.UnitSim.PokemonBenefits_Weather( opponentAlly, nextWeather ) )
            theirPBF.BenefitWeather = true;

