public class StrategyPressureEvidence
{
    public StrategyPressure Pressure;
    public PairStrategyIntent SourceStrategy;
    public ActionType SourceAction;
    public IActionResult SourceActionResult;
    public Dictionary<Pokemon, HashSet<CapabilityObservation>> ResponseCapabilities;

    public void InitRC()
    {
        if( ResponseCapabilities == null || ResponseCapabilities.Count <= 0 )
            ResponseCapabilities = new();
    }

    public bool TryGet_AfterYouInfo( out IBattleAIUnit afterYouTarget )
    {
        if( SourceStrategy == null && Pressure == StrategyPressure.None )
        {
            afterYouTarget = null;
            return false;
        }

        if( SourceStrategy?.Strategy == PairStrategy.AfterYouAttack || Pressure == StrategyPressure.AfterYou )
        {
            if( SourceActionResult is StatusThreatResult scr && scr.Move.MoveSO.Name == "After You" && scr.Targets?.Count == 1 )
            {
                afterYouTarget = scr.Targets[0];
                return true;
            }
            else
            {
                var leftIntent = SourceStrategy.LeftIntent;
                if( leftIntent.IntentResult is StatusThreatResult leftSCR && leftSCR.Move?.MoveSO.Name == "After You" && leftSCR.Targets?.Count == 1 )
                {
                    afterYouTarget = leftSCR.Targets[0];
                    return true;
                }

                var rightIntent = SourceStrategy.RightIntent;
                if( leftIntent.IntentResult is StatusThreatResult rightSCR && rightSCR.Move?.MoveSO.Name == "After You" && rightSCR.Targets?.Count == 1 )
                {
                    afterYouTarget = rightSCR.Targets[0];
                    return true;
                }
            }
        }

        afterYouTarget = null;
        return false;
    }

    public bool TryGet_QuashInfo( out IBattleAIUnit quashTarget )
    {
        // if( SourceStrategy.Strategy == PairStrategy.QuashStrategies || Pressure == StrategyPressure.Quash )
        // {
        //     if( SourceActionResult is StatusThreatResult scr && scr.Move.MoveSO.Name == "Quash" && scr.Targets?.Count == 1 )
        //     {
        //         quashTarget = scr.Targets[0];
        //         return true;
        //     }
        //     else
        //     {
        //         var leftIntent = SourceStrategy.LeftIntent;
        //         if( leftIntent.IntentResult is StatusThreatResult leftSCR && leftSCR.Move?.MoveSO.Name == "Quash" && leftSCR.Targets?.Count == 1 )
        //         {
        //             quashTarget = leftSCR.Targets[0];
        //             return true;
        //         }

        //         var rightIntent = SourceStrategy.RightIntent;
        //         if( rightIntent.IntentResult is StatusThreatResult rightSCR && rightSCR.Move?.MoveSO.Name == "Quash" && rightSCR.Targets?.Count == 1 )
        //         {
        //             quashTarget = rightSCR.Targets[0];
        //             return true;
        //         }
        //     }
        // }

        quashTarget = null;
        return false;
    }
}

