public struct InteractionFlags
{
    public bool StrongestAttack;
    public bool RawSwitch;

    public bool SetAbilityWeather;
    public bool SetMoveWeather;
    public bool SetAbilityTerrain;
    public bool SetMoveTerrain;

    public bool SetTrickRoom;
    public bool SetTailwind;

    public bool SetReflect;
    public bool SetLightScreen;
    public bool SetAuroraVeil;

    public bool SetEntryHazard;

    public bool FakeOut;
