public struct InteractionProfile
{
    public IBattleAIUnit Attacker;
    public IBattleAIUnit Target;
    public IBattleAIUnit AttackerAlly;
    public IBattleAIUnit TargetAlly;

    public PotentialToKO AttackerPTKO;
    public PotentialToKO TargetPTKO;

    public bool AttackerMovesFirst;
    public Dictionary<Pokemon, int> TurnOrder;

    public UnitComparison UsVsThem;
    public UnitComparison UsVsTheirAlly;
    public UnitComparison OurAllyVsThem;
    public UnitComparison OurAllyVsTheirAlly;

    public ActionType OurAction;
    public ActionType OurAllyAction;
    public ActionType TheirAction;
    public ActionType TheirAllyAction;

    public bool TheirAllyHasIntent;
    public IActionResult TheirActionResult;
    public IActionResult TheirAllyActionResult;

    public InteractionFlags WeCan;
    public InteractionFlags TheyCan;
    public InteractionFlags TheyWant;
}

public struct AllySynergyProfile
{
    public IBattleAIUnit Attacker;
    public IBattleAIUnit AttackerAlly;

    public InteractionFlags WeCan;
    public InteractionFlags AllyCan;
}

